using System.Collections.Generic;
using System.Linq;
using Rapadura.Core.Localization;

namespace Rapadura.Gameplay.World.Cities
{
    /// <summary>
    /// Localization (en + pt-BR) of the city side quests (<see cref="CityQuestCatalog"/>): title, description, objectives
    /// and journal (<c>quest.city_*</c>, the same shape as the region quests) and the giver's offer/progress lines. Merged
    /// into the live manager by <see cref="EnsureLoaded"/> (keys it already has win), like <c>RegionQuestTexts</c>.
    /// </summary>
    public static class CityQuestTexts
    {
        public static readonly List<LocalizationEntry> All = new List<LocalizationEntry>
        {
            // ================= Copas de Garajonay — Gara, guardiã das copas =================
            new LocalizationEntry("quest.city_garajonay_dry_mist.title", "The Mist That Forgot the Water", "A Névoa Que Esqueceu a Água"),
            new LocalizationEntry("quest.city_garajonay_dry_mist.description",
                "Since the shadow drank the mist, the laurel lizards of the forest floor run wild and dry. Gara, the canopy warden of Copas de Garajonay, asked the cousins to calm them before they climb the trunks.",
                "Desde que a sombra bebeu a névoa, os lagartos do chão da mata de louro andam bravos e secos. Gara, a guardiã das copas de Garajonay, pediu aos primos que os acalmem antes que subam pelos troncos."),
            new LocalizationEntry("quest.city_garajonay_dry_mist.obj_calm_mist_lizards", "Calm the wild beasts of the laurel floor", "Acalmar os bichos bravos do chão da mata de louro"),
            new LocalizationEntry("quest.city_garajonay_dry_mist.journal",
                "Gara says the laurels drink the cloud and the cloud remembers everything. Grandpa Jorge's tales said the same about the rain that comes sideways. Five of us, one mist.",
                "A Gara diz que o louro bebe a nuvem e a nuvem lembra de tudo. Os contos do Vô Jorge falavam a mesma coisa da chuva que vem de lado. Somos cinco, a névoa é uma só."),
            new LocalizationEntry("quest.city_garajonay_dry_mist.offer",
                "Grandma Edna's grandchildren, at last! The mist forgot the water and the forest floor went wild. Calm six of the beasts down there and the bridges will sing for you.",
                "Os netos da Vó Edna, enfim! A névoa esqueceu a água e o chão da mata ficou bravo. Acalmem seis bichos lá embaixo e as pontes vão cantar para vocês."),
            new LocalizationEntry("quest.city_garajonay_dry_mist.active",
                "The mist is still dry down there. Walk in pairs on the trails: whoever falls from a bridge comes back the long way.",
                "A névoa ainda está seca lá embaixo. Andem em dupla pelas trilhas: quem cai da ponte volta pelo caminho comprido."),

            // ================= Copas de Garajonay — Tinguaro, o rastreador =================
            new LocalizationEntry("quest.city_garajonay_moss_tracks.title", "Tracks in the Moss", "Rastros no Musgo"),
            new LocalizationEntry("quest.city_garajonay_moss_tracks.description",
                "Moss boars dimmed by the shadow are digging up the roots of the giant laurels. Tinguaro, the elves' tracker, read their tracks and needs the cousins to chase them off.",
                "Javalis de musgo apagados pela sombra estão revirando as raízes dos louros gigantes. Tinguaro, o rastreador dos elfos, leu os rastros e precisa dos primos para espantá-los."),
            new LocalizationEntry("quest.city_garajonay_moss_tracks.obj_follow_moss_boars", "Chase off the moss boars", "Espantar javalis de musgo"),
            new LocalizationEntry("quest.city_garajonay_moss_tracks.journal",
                "Tinguaro reads moss the way Ícaro reads gears. He says a track is a letter the animal forgot to send. Maithe wants to learn it all.",
                "O Tinguaro lê musgo do jeito que o Ícaro lê engrenagem. Ele diz que rastro é carta que o bicho esqueceu de mandar. A Maithe quer aprender tudo."),
            new LocalizationEntry("quest.city_garajonay_moss_tracks.offer",
                "Gara told me you calmed the floor. Now the moss boars are digging at the laurel roots. Five of them, and I'll give you one of Jonay's bows.",
                "A Gara me contou que vocês acalmaram o chão. Agora os javalis de musgo estão cavando as raízes dos louros. Cinco deles, e eu te dou um dos arcos do Jonay."),
            new LocalizationEntry("quest.city_garajonay_moss_tracks.active",
                "Follow the turned moss, not the noise. A boar that is running is not where the noise is.",
                "Sigam o musgo revirado, não o barulho. Javali que corre não está onde o barulho está."),

            // ================= Taa Pwani — Capitão Liyongo, o nakhoda =================
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.title", "Thieves of the Sails", "Ladras de Vela"),
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.description",
                "Gulls dimmed by the shadow swoop on the dhows of Taa Pwani, tear the triangular sails and steal the rope. Captain Liyongo, the nakhoda of the harbour, cannot sail for the reef until they are driven off.",
                "Gaivotas apagadas pela sombra mergulham nos dhows de Taa Pwani, rasgam as velas triangulares e roubam a corda. O Capitão Liyongo, o nakhoda do porto, não consegue sair para o recife enquanto elas não forem espantadas."),
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.obj_drive_off_thief_gulls", "Drive off the thief gulls", "Espantar as gaivotas ladras"),
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.journal",
                "Captain Liyongo says the monsoon pushes one way half the year and back the other half. Grandpa Jorge sailed with these people once: Mbaraka still remembers his off-key songs on deck.",
                "O Capitão Liyongo diz que a monção empurra para um lado meio ano e volta no outro meio. O Vô Jorge já navegou com esse povo: o Mbaraka ainda lembra das cantorias desafinadas dele no convés."),
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.offer",
                "Grandma Edna's five, on my quay! Karibu. The gulls went grey and mean, they tear my sails faster than we can sew. Drive six of them off and the first wind of the monsoon is yours.",
                "Os cinco da Vó Edna, no meu cais! Karibu. As gaivotas ficaram cinzentas e malvadas, rasgam as velas mais rápido do que a gente costura. Espantem seis delas e o primeiro vento da monção é de vocês."),
            new LocalizationEntry("quest.city_taa_pwani_thief_gulls.active",
                "Still gulls over the reef. Watch the sky at low tide: they dive when the sails are drying.",
                "Ainda tem gaivota em cima do recife. Olhem o céu na maré baixa: elas mergulham quando as velas estão secando."),

            // ================= Taa Pwani — Zawadi, o trançador de raízes =================
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.title", "Claws in the Mangrove", "Garras no Mangue"),
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.description",
                "Giant crabs gone dim are cutting the living roots of the mangroves Zawadi braids his boots from. Without the roots, nobody walks the mud of Liyongo's mangroves.",
                "Caranguejos gigantes apagados estão cortando as raízes vivas dos mangues de onde o Zawadi trança as botas. Sem as raízes, ninguém anda no lodo dos mangues de Liyongo."),
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.obj_cut_free_the_roots", "Free the roots from the giant claws", "Livrar as raízes das garras gigantes"),
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.journal",
                "Zawadi only braids the roots that fall on their own. He says the mangrove gives what it can spare, like Grandma Edna's orchard. Joaquim doesn't sink in the mud, but he wants a pair anyway.",
                "O Zawadi só trança as raízes que caem sozinhas. Ele diz que o mangue dá o que pode, igual ao pomar da Vó Edna. O Joaquim não afunda no lodo, mas quer um par mesmo assim."),
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.offer",
                "The captain says you can handle gulls. Can you handle claws? Five giant crabs are cutting my roots. Free them and the first pair of root boots of the tide is yours.",
                "O capitão diz que vocês dão conta de gaivota. E de garra? Cinco caranguejos gigantes estão cortando as minhas raízes. Livrem elas e o primeiro par de botas de raiz da maré é de vocês."),
            new LocalizationEntry("quest.city_taa_pwani_mangrove_claws.active",
                "Pole pole: a crab backs off sideways. Wait for it to open its claws, then strike.",
                "Pole pole: caranguejo recua de lado. Espera ele abrir a garra, aí bate."),

            // ================= Tambor Rubro — Gurparanzah, a chefe-arqueira =================
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.title", "Red Tails on the Mesa", "Caudas Vermelhas na Mesa"),
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.description",
                "Scorpions gone dim by the shadow nest in the cracks of the badlands and sting the clans' wolves on the way to the forge. Gurparanzah, the archer chief of the Tambor Rubro, wants the road to the canyons clear before the next drum.",
                "Escorpiões apagados pela sombra fazem ninho nas fendas dos ermos e picam os lobos dos clãs no caminho da forja. A Gurparanzah, chefe-arqueira do Tambor Rubro, quer a estrada dos cânions limpa antes do próximo tambor."),
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.obj_clear_red_scorpions", "Clear the red scorpions from the canyon road", "Limpar os escorpiões rubros da estrada dos cânions"),
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.journal",
                "Gurparanzah says an orc's word weighs more than an orc's axe. Grandpa Jorge once gave her his word he'd bring a sack of Grandma Edna's apricots, and he did, through a sandstorm.",
                "A Gurparanzah diz que palavra de orc pesa mais que machado de orc. O Vô Jorge uma vez deu a palavra de trazer um saco de damascos da Vó Edna, e trouxe, no meio de uma tempestade de areia."),
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.offer",
                "The grandchildren of Jorge and Edna, inside my palisade! Then you keep your word like he did. Six red scorpions are nesting on the canyon road. Clear them and the forge drum will play your names tonight.",
                "Os netos do Jorge e da Edna, dentro da minha paliçada! Então vocês cumprem a palavra como ele cumpria. Seis escorpiões rubros fizeram ninho na estrada dos cânions. Limpem e o tambor da forja toca o nome de vocês hoje à noite."),
            new LocalizationEntry("quest.city_tambor_rubro_red_scorpions.active",
                "Still tails on the road. They hide in the shade of the chimneys of stone at noon: look there first.",
                "Ainda tem cauda na estrada. Ao meio-dia eles se escondem na sombra das chaminés de pedra: olhem lá primeiro."),

            // ================= Tambor Rubro — Kessi, o caçador =================
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.title", "Hawks of Ember", "Gaviões de Brasa"),
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.description",
                "Hawks gone dim dive on the camp's hide racks and carry off the meat the drums were going to share. Kessi, the hunter of the Tambor Rubro, never hunts more than the camp eats: five of them, and not one more.",
                "Gaviões apagados mergulham nos varais de couro do acampamento e levam a carne que os tambores iam repartir. O Kessi, caçador do Tambor Rubro, nunca caça mais do que o acampamento come: cinco deles, nem um a mais."),
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.obj_hunt_ember_hawks", "Hunt the ember hawks", "Caçar os gaviões de brasa"),
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.journal",
                "Kessi hunts with the drum's rhythm: three beats to aim, one to loose. Maithe says she'll try it. Lavine says the hawks were only hungry, and Kessi agrees with her.",
                "O Kessi caça no ritmo do tambor: três batidas para mirar, uma para soltar. A Maithe diz que vai tentar. A Lavine diz que os gaviões só estavam com fome, e o Kessi concorda com ela."),
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.offer",
                "Gurparanzah says you keep your word. Good: so do I. Five ember hawks are robbing the racks. Bring them down and take this theriac: the Throne of Namrael is all poison, you'll need it.",
                "A Gurparanzah diz que vocês cumprem a palavra. Bom: eu também. Cinco gaviões de brasa estão roubando os varais. Derrubem eles e levem esta teriaga: o Trono de Namrael é só veneno, vocês vão precisar."),
            new LocalizationEntry("quest.city_tambor_rubro_ember_hawks.active",
                "Watch the sky over the canyons. A hawk that is circling is still deciding; strike when it dives.",
                "Olhem o céu em cima dos cânions. Gavião que está rodando ainda está decidindo; acertem quando ele mergulhar."),

            // ================= Salões de Bronze — Untash, o mestre de obras =================
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.title", "Slag on the Stairs", "Escória na Escada"),
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.description",
                "Since the Grande Forja went cold, badly cast golems of slag wander the stairs between the halls and the mines, and the dwarves can no longer carry ore down. Untash, master builder of the Bronze Halls, wants the stairs clear before he starts on the new bellows.",
                "Desde que a Grande Forja apagou, golens mal fundidos de escória andam pelas escadas entre os salões e as minas, e os anões não conseguem mais descer o minério. O Untash, mestre de obras dos Salões de Bronze, quer as escadas livres antes de começar o fole novo."),
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.obj_break_slag_golems", "Break the slag golems on the mine stairs", "Quebrar os golens de escória da escada das minas"),
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.journal",
                "Untash measures everything twice and builds once. He says Grandpa Jorge once fixed a hinge here with a piece of string, and that the hinge still holds, which annoys him very much.",
                "O Untash mede tudo duas vezes e constrói uma. Ele diz que o Vô Jorge uma vez consertou uma dobradiça daqui com um pedaço de barbante, e que a dobradiça segura até hoje, o que irrita ele muito."),
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.offer",
                "Jorge's grandchildren! Good. I need hands that don't ask how long it will take. Five slag golems are blocking the mine stairs: bad castings, poor things, walking without anyone telling them where. Break them, and bring back any bronze you find.",
                "Os netos do Jorge! Bom. Preciso de mãos que não perguntam quanto tempo vai levar. Cinco golens de escória estão trancando a escada das minas: fundição ruim, coitados, andando sem ninguém dizer para onde. Quebrem eles, e tragam o bronze que acharem."),
            new LocalizationEntry("quest.city_saloes_de_bronze_slag_golems.active",
                "A slag golem is slow but it doesn't stop. Hit the cracks where the casting cooled wrong.",
                "Golem de escória é lento, mas não para. Batam nas rachaduras onde a fundição esfriou errado."),

            // ================= Salões de Bronze — Shilhak, o minerador =================
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.title", "Bats in the Seam", "Morcegos no Veio"),
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.description",
                "Bats that nested in the last warm cracks of the forge have gone dim and swarm whoever lights a lamp in Shilhak's seam. Without that seam there is no bronze, and without bronze there is no new bellows for the Grande Forja.",
                "Morcegos que se aninharam nas últimas fendas quentes da forja ficaram apagados e atacam quem acende lamparina no veio do Shilhak. Sem esse veio não tem bronze, e sem bronze não tem fole novo para a Grande Forja."),
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.obj_drive_out_ember_bats", "Drive the ember bats out of the seam", "Expulsar os morcegos de brasa do veio"),
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.journal",
                "Shilhak sings to the rock before he swings the pick. Joaquim tried it and the rock answered with an echo. Maria says that counts.",
                "O Shilhak canta para a pedra antes de bater a picareta. O Joaquim tentou e a pedra respondeu com eco. A Maria diz que conta."),
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.offer",
                "Untash says you break slag like real dwarves. Then come down to my seam: six swarms of ember bats won't let a lamp burn. Clear them out and I'll give you a pot of ginger tea. Up on the Mazans' summit the wind cuts like a chisel.",
                "O Untash diz que vocês quebram escória como anão de verdade. Então desçam no meu veio: seis bandos de morcegos de brasa não deixam lamparina acesa. Tirem eles de lá e eu dou um pote de chá de gengibre. Lá no cume dos Mazans o vento corta feito talhadeira."),
            new LocalizationEntry("quest.city_saloes_de_bronze_ember_bats.active",
                "Bats go for the light. Hold the lamp high, let them come, and swing low.",
                "Morcego vai atrás da luz. Segurem a lamparina no alto, deixem eles virem, e batam baixo."),

            // ================= Mercado dos Túneis — Takhsich, o inventor =================
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.title", "Webs in the Pipes", "Teia nos Tubos"),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.description",
                "Spiders have spun so much web over the mouths of the air pipes that Takhsich's fans can no longer pull the Ar Sereno down from the cracks, and the market's air is going still. The inventor of the Tunnel Market wants his pipes breathing again.",
                "As aranhas teceram tanta teia na boca dos tubos de ar que os cata-ventos do Takhsich não conseguem mais puxar o Ar Sereno das frestas, e o ar do mercado está ficando parado. O inventor do Mercado dos Túneis quer os tubos respirando de novo."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.obj_clear_webbed_pipes", "Clear the spiders from the air pipes", "Tirar as aranhas dos tubos de ar"),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.journal",
                "Takhsich and Ícaro spent an hour drawing a fan with seven blades. Then an hour taking two away. Lavine says the spiders only wanted somewhere warm.",
                "O Takhsich e o Ícaro passaram uma hora desenhando um cata-vento de sete pás. Depois uma hora tirando duas. A Lavine diz que as aranhas só queriam um lugar quentinho."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.offer",
                "You came in through the north gallery? Then you felt it: the air is still. Six spiders are webbing my pipes shut. Clear them and I'll show you how the fan works. And here, an oil lamp, for the dark bits, and two bottles of the air they were stealing.",
                "Vocês entraram pela galeria norte? Então sentiram: o ar está parado. Seis aranhas estão tecendo meus tubos fechados. Tirem elas e eu mostro como o cata-vento funciona. E toma, uma lamparina, para os pedaços escuros, e duas garrafas do ar que elas estavam roubando."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_webbed_pipes.active",
                "Follow the pipes: where the fan stops, there's a spider.",
                "Sigam os tubos: onde o cata-vento para, tem aranha."),

            // ================= Mercado dos Túneis — Farnkhund, o vagoneiro =================
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.title", "Stones on the Rails", "Pedras nos Trilhos"),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.description",
                "Stone golems have wandered onto the cart rails that bring the market's goods from the Wheel Canyon, and Farnkhund's carts stop dead in front of them. The cart driver of the tunnels wants the line clear, and pays in the oil that never goes out.",
                "Golens de pedra entraram nos trilhos dos vagonetes que trazem as mercadorias do Cânion da Roda, e os vagonetes do Farnkhund param em seco na frente deles. O vagoneiro dos túneis quer a linha livre, e paga com o óleo que nunca apaga."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.obj_clear_the_rails", "Clear the stone golems off the cart rails", "Tirar os golens de pedra dos trilhos dos vagonetes"),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.journal",
                "Farnkhund knows every switch of the tunnels by its squeak. Maithe timed one of his carts and it beat her. She wants a rematch.",
                "O Farnkhund conhece cada desvio dos túneis pelo rangido. A Maithe cronometrou um vagonete dele e perdeu. Ela quer revanche."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.offer",
                "Takhsich's pipes are breathing, so you're good with your hands. Four stone golems are sitting on my rails like they bought them. Get them off and take this oil: down in the Wheel Canyon only the eternal fire stays lit.",
                "Os tubos do Takhsich estão respirando, então vocês são bons de mão. Quatro golens de pedra estão sentados nos meus trilhos como se tivessem comprado. Tirem eles e levem este óleo: lá no Cânion da Roda só o fogo eterno fica aceso."),
            new LocalizationEntry("quest.city_mercado_dos_tuneis_stones_on_the_rails.active",
                "A golem on a rail can't turn. Come at it from the side, never from in front.",
                "Golem em cima do trilho não vira. Cheguem pelo lado, nunca pela frente."),

            // ================= Aratta — Enmerkar, o chefe construtor =================
            new LocalizationEntry("quest.city_aratta_grass_jackals.title", "Jackals in the Dry Grass", "Chacais no Capim Seco"),
            new LocalizationEntry("quest.city_aratta_grass_jackals.description",
                "Jackals dimmed by the shadow hide in the old grass that the Fogo Vivo has not renewed yet, and fall on the calves of Aratta's herds. Enmerkar, the chief builder, wants the pens safe before the next low burn.",
                "Chacais apagados pela sombra se escondem no capim velho que o Fogo Vivo ainda não renovou, e caem em cima dos bezerros dos rebanhos de Aratta. Enmerkar, o chefe construtor, quer os cercados seguros antes da próxima queimada baixa."),
            new LocalizationEntry("quest.city_aratta_grass_jackals.obj_drive_off_grass_jackals", "Drive the jackals out of the dry grass", "Espantar os chacais do capim seco"),
            new LocalizationEntry("quest.city_aratta_grass_jackals.journal",
                "Enmerkar writes everything on clay: how many calves, how many pens, how many jackals. Maria says he even wrote our names. Ícaro wants to know how the clay keeps the words.",
                "O Enmerkar escreve tudo na argila: quantos bezerros, quantos cercados, quantos chacais. A Maria diz que ele até escreveu os nossos nomes. O Ícaro quer saber como a argila guarda as palavras."),
            new LocalizationEntry("quest.city_aratta_grass_jackals.offer",
                "Edna's grandchildren! I wrote you would come, and here you are: the clay never lies. Six jackals are hiding in the old grass and the calves cry at night. Drive them off and Aratta will owe you a song.",
                "Os netos da Edna! Eu escrevi que vocês viriam, e aqui estão: a argila nunca mente. Seis chacais estão escondidos no capim velho e os bezerros choram de noite. Espantem eles e Aratta vai dever uma canção a vocês."),
            new LocalizationEntry("quest.city_aratta_grass_jackals.active",
                "The jackals hate the burnt strips. Walk the black paths and they come to you in the open.",
                "Os chacais detestam as faixas queimadas. Andem pelos caminhos pretos e eles vêm até vocês no aberto."),

            // ================= Aratta — Shulgi, o corredor =================
            new LocalizationEntry("quest.city_aratta_shulgi_course.title", "The Course of Shulgi", "O Percurso de Shulgi"),
            new LocalizationEntry("quest.city_aratta_shulgi_course.description",
                "Baboons gone wild sit on the marked course of the Corrida de Shulgi and throw stones at whoever runs past. Shulgi, the runner of Aratta, cannot train, and the race ribbons are waiting.",
                "Babuínos bravos sentaram no percurso marcado da Corrida de Shulgi e jogam pedra em quem passa correndo. Shulgi, o corredor de Aratta, não consegue treinar, e as fitas de corrida estão esperando."),
            new LocalizationEntry("quest.city_aratta_shulgi_course.obj_clear_the_course", "Clear the baboons off the race course", "Tirar os babuínos do percurso da corrida"),
            new LocalizationEntry("quest.city_aratta_shulgi_course.journal",
                "Shulgi says he once ran from one city to another in a single day, and back. Maithe believes him. Joaquim asked for a rest halfway through the explanation.",
                "O Shulgi diz que uma vez correu de uma cidade até outra num dia só, e voltou. A Maithe acredita. O Joaquim pediu para descansar no meio da explicação."),
            new LocalizationEntry("quest.city_aratta_shulgi_course.offer",
                "Enmerkar's pens are safe, so you're fast enough for me. Five baboons are sitting on my course like judges. Get them off and take these waterskins: out on the savanna, whoever drinks last runs first.",
                "Os cercados do Enmerkar estão seguros, então vocês são rápidos o bastante para mim. Cinco babuínos estão sentados no meu percurso feito juízes. Tirem eles de lá e levem estes odres: lá na savana, quem bebe por último corre na frente."),
            new LocalizationEntry("quest.city_aratta_shulgi_course.active",
                "Follow the horn posts with the blue ribbons: the course runs from one to the next.",
                "Sigam os postes de chifre com fita azul: o percurso vai de um para o outro."),

            // ================= Kirta — Kirta, o rei =================
            new LocalizationEntry("quest.city_kirta_reef_ooze.title", "Ooze on the Reef", "Lodo no Recife"),
            new LocalizationEntry("quest.city_kirta_reef_ooze.description",
                "The Lodo has crept over the reef in living lumps that smother the coral and put out its colour. King Kirta, who lost everything to the sea once and rebuilt it all, asked the cousins to scrape the ooze off before it reaches the mother coral.",
                "O Lodo se espalhou pelo recife em bolotas vivas que abafam o coral e apagam a cor dele. O rei Kirta, que já perdeu tudo para o mar uma vez e reconstruiu tudo, pediu aos primos que raspem o lodo antes que chegue ao coral-mãe."),
            new LocalizationEntry("quest.city_kirta_reef_ooze.obj_scrape_the_ooze", "Scrape the living ooze off the reef", "Raspar o lodo vivo do recife"),
            new LocalizationEntry("quest.city_kirta_reef_ooze.journal",
                "Where the ooze came off, the coral blushed pink in a breath. Lavine says it was holding its breath all this time. Kirta smiled for the first time today.",
                "Onde o lodo saiu, o coral ficou rosa num suspiro. A Lavine diz que ele estava prendendo a respiração esse tempo todo. O Kirta sorriu pela primeira vez hoje."),
            new LocalizationEntry("quest.city_kirta_reef_ooze.offer",
                "Edna's grandchildren, walking on my reef. Jorge told me you would come when the coral went grey. Six lumps of the Lodo are smothering the east reef. Scrape them off and the coral will remember its colour.",
                "Os netos da Edna, andando no meu recife. O Jorge me disse que vocês viriam quando o coral ficasse cinza. Seis bolotas do Lodo estão abafando o recife do leste. Raspem elas e o coral vai lembrar da cor."),
            new LocalizationEntry("quest.city_kirta_reef_ooze.active",
                "The ooze hides where the coral is greyest. Follow the grey.",
                "O lodo se esconde onde o coral está mais cinza. Sigam o cinza."),

            // ================= Kirta — Pughat, a que cuida de todos =================
            new LocalizationEntry("quest.city_kirta_divers_rescue.title", "The Cornered Divers", "Os Mergulhadores Encurralados"),
            new LocalizationEntry("quest.city_kirta_divers_rescue.description",
                "Lantern fish dimmed by the Lodo have cornered three of Kirta's pearl divers in a grotto of the reef, and their air is running out. Pughat, who looks after everyone, is going in, and she wants the cousins with her.",
                "Peixes-lanterna apagados pelo Lodo encurralaram três mergulhadores de pérola de Kirta numa gruta do recife, e o ar deles está acabando. A Pughat, que cuida de todo mundo, vai entrar, e quer os primos junto."),
            new LocalizationEntry("quest.city_kirta_divers_rescue.obj_free_the_divers", "Drive off the lantern fish around the divers' grotto", "Afastar os peixes-lanterna da gruta dos mergulhadores"),
            new LocalizationEntry("quest.city_kirta_divers_rescue.journal",
                "Pughat counted the divers twice when they came out: three in, three out. Then she counted us. Five. She says that is the only sum that matters.",
                "A Pughat contou os mergulhadores duas vezes quando eles saíram: três entraram, três saíram. Depois contou a gente. Cinco. Ela diz que essa é a única conta que importa."),
            new LocalizationEntry("quest.city_kirta_divers_rescue.offer",
                "You scraped the reef for my king, now help me with my divers. Five lantern fish have them cornered in the grotto. Drive them off and take this bubble of air: down in Sunken Kilwa every house is under water.",
                "Vocês rasparam o recife para o meu rei, agora me ajudem com os meus mergulhadores. Cinco peixes-lanterna encurralaram eles na gruta. Afastem os peixes e levem esta bolha de ar: lá em Kilwa Afundada toda casa fica debaixo d'água."),
            new LocalizationEntry("quest.city_kirta_divers_rescue.active",
                "Lantern fish chase the light. Cover your lamps, come from the dark side.",
                "Peixe-lanterna corre atrás da luz. Cubram as lamparinas, cheguem pelo lado escuro."),

            // ================= Jhilpur — Salmaios, o velho da Raiz-Mãe =================
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.title", "Ooze on the Ghats", "Lodo nos Ghats"),
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.description",
                "Living lumps of the Lodo climb the brick steps of the ghats a little higher every night, and old Salmaios, who has tended the Raiz-Mãe since before the city had a name, fears they will reach its roots. He asked the cousins to scrape them off the steps.",
                "Bolotas vivas do Lodo sobem os degraus de tijolo dos ghats um pouco mais a cada noite, e o velho Salmaios, que cuida da Raiz-Mãe desde antes de a cidade ter nome, tem medo de que cheguem às raízes dela. Ele pediu aos primos que raspem o lodo dos degraus."),
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.obj_scrape_the_ghats", "Scrape the living ooze off the ghats", "Raspar o lodo vivo dos ghats"),
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.journal",
                "When the last lump slid back into the water, the ring at the foot of the Raiz-Mãe shone green for a moment. Joaquim swears the tree sighed. Salmaios just nodded, as if it had said thank you.",
                "Quando a última bolota escorregou de volta para a água, o anel no pé da Raiz-Mãe brilhou verde por um instante. O Joaquim jura que a árvore suspirou. O Salmaios só acenou com a cabeça, como se ela tivesse dito obrigado."),
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.offer",
                "Edna's grandchildren, in my roots. Jorge sat on these same steps forty monsoons ago. Seven lumps of the Lodo are climbing the ghats tonight. Scrape them off before they touch the Raiz-Mãe, and the Living Water will run clean at her feet again.",
                "Os netos da Edna, nas minhas raízes. O Jorge sentou nesses mesmos degraus há quarenta monções. Sete bolotas do Lodo estão subindo os ghats hoje. Raspem elas antes que encostem na Raiz-Mãe, e a Água Viva vai correr limpa nos pés dela de novo."),
            new LocalizationEntry("quest.city_jhilpur_ooze_on_the_ghats.active",
                "The ooze comes up where the steps are darkest. Follow the dark steps down.",
                "O lodo sobe onde os degraus estão mais escuros. Desçam pelos degraus escuros."),

            // ================= Jhilpur — Abiesous, o mestre da escola de barco =================
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.title", "Crows on the Oars", "Corvos nos Remos"),
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.description",
                "Crows dimmed by the Lodo have taken the roof of Abiesous's boat school and steal the oars right out of the pupils' hands. The master teaches patience, but the monsoon is coming and nobody can learn to row without an oar.",
                "Corvos apagados pelo Lodo tomaram o telhado da escola de barco do Abiesous e roubam os remos da mão dos alunos. O mestre ensina paciência, mas a monção está chegando e ninguém aprende a remar sem remo."),
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.obj_chase_the_crows", "Chase the dimmed crows off the boat school", "Espantar os corvos apagados da escola de barco"),
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.journal",
                "The oars came back, one by one, and Abiesous counted them like a teacher counts pupils after a storm. Then he gave Lavine the first lesson for free. She rowed in a circle. He called it a good start.",
                "Os remos voltaram, um por um, e o Abiesous contou todos como um professor conta os alunos depois de uma tempestade. Depois deu a primeira aula de graça para a Lavine. Ela remou em círculo. Ele disse que foi um bom começo."),
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.offer",
                "You cleaned Salmaios's steps, so you are patient enough for my school. Six crows are sitting on my roof with my oars. Chase them off and take this purifying fruit: down in the Heart of the Mire the water is so black that only it lets you breathe.",
                "Vocês limparam os degraus do Salmaios, então têm paciência o bastante para a minha escola. Seis corvos estão sentados no meu telhado com os meus remos. Espantem eles e levem esta fruta purificadora: lá no Coração do Lodo a água é tão preta que só ela deixa a gente respirar."),
            new LocalizationEntry("quest.city_jhilpur_boat_school_crows.active",
                "Crows love what shines. Wave a lantern and they will come down to you.",
                "Corvo gosta do que brilha. Balancem uma lanterna e eles descem até vocês."),

            // ================= Palafitas de Tarchon — Tarchon, o fundador =================
            new LocalizationEntry("quest.city_tarchon_caught_wisps.title", "Caught Wisps", "Fogos-Fátuos Presos"),
            new LocalizationEntry("quest.city_tarchon_caught_wisps.description",
                "Every night the swamp round the stilts fills with will-o'-wisps: sparks of light caught in the reeds, buzzing and angry. Half the trols have stared at them so long that they forgot who they were. Old Tarchon, who drove the first pile into this mud, asked the cousins to set them free.",
                "Toda noite o pântano em volta das palafitas enche de fogos-fátuos: faíscas de luz presas no junco, zumbindo, bravas. Metade dos trols olhou tanto para elas que esqueceu quem era. O velho Tarchon, que fincou a primeira estaca nessa lama, pediu aos primos que soltem elas."),
            new LocalizationEntry("quest.city_tarchon_caught_wisps.obj_free_the_wisps", "Set the caught will-o'-wisps free", "Libertar os fogos-fátuos presos"),
            new LocalizationEntry("quest.city_tarchon_caught_wisps.journal",
                "The last wisp went up slowly, like a bubble, and hung over the mast for a moment before it went on to the sky. On the boardwalk, a trol who had not spoken for a year said good evening. Tarchon cried a little. Very slowly.",
                "O último fogo-fátuo subiu devagar, como uma bolha, e ficou um instante em cima do mastro antes de seguir para o céu. Na passarela, um trol que não falava fazia um ano disse boa noite. O Tarchon chorou um pouco. Bem devagar."),
            new LocalizationEntry("quest.city_tarchon_caught_wisps.offer",
                "Edna's... grandchildren. Jorge... rowed here... once. Lost. Laughing. Eight sparks... are caught... in the reeds tonight. They are not... wicked. Only... lost. Let them... go home.",
                "Os netos... da Edna. O Jorge... remou até aqui... uma vez. Perdido. Rindo. Oito faíscas... estão presas... no junco hoje. Elas não são... más. Só... perdidas. Deixem elas... voltar para casa."),
            new LocalizationEntry("quest.city_tarchon_caught_wisps.active",
                "Wisps... buzz louder... near the water. Follow... the buzzing.",
                "Os fogos-fátuos... zumbem mais alto... perto da água. Sigam... o zumbido."),

            // ================= Palafitas de Tarchon — Vel, o pescador =================
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.title", "Herons on the Nets", "Garças nas Redes"),
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.description",
                "Pale ghost birds, dimmed by the Lodo, stand on the poles of Vel's nets all night and steal every catfish he catches. Vel is too gentle to chase anything away; he asked the cousins to do it for him.",
                "Pássaros pálidos, apagados pelo Lodo, ficam a noite inteira nos varais das redes do Vel e roubam todo bagre que ele pega. O Vel é manso demais para espantar qualquer coisa; pediu aos primos que façam isso por ele."),
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.obj_chase_the_herons", "Chase the ghost birds off Vel's nets", "Espantar os pássaros-fantasma das redes do Vel"),
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.journal",
                "The nets came up full for the first time in weeks. Vel counted the catfish twice, gave the fattest one to Maria and laughed so hard the boardwalk shook. Then he hung an amulet round Lavine's neck: \"For the bog. The dragon is shy, but the snakes are not.\"",
                "As redes subiram cheias pela primeira vez em semanas. O Vel contou os bagres duas vezes, deu o mais gordo para a Maria e riu tanto que a passarela tremeu. Depois pendurou um amuleto no pescoço da Lavine: \"Para o charco. A dragoa é tímida, mas as cobras não são.\""),
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.offer",
                "You freed the wisps. Tarchon smiled. Took him... a year. Now... my nets. Six pale birds... on my poles. Every night. Chase them... and take this amulet. In the Ninki Nanka's bog... the snakes bite.",
                "Vocês soltaram os fogos-fátuos. O Tarchon sorriu. Levou... um ano. Agora... as minhas redes. Seis pássaros pálidos... nos meus varais. Toda noite. Espantem eles... e levem este amuleto. No charco do Ninki Nanka... as cobras mordem."),
            new LocalizationEntry("quest.city_tarchon_herons_on_the_nets.active",
                "They come... when the mist is lilac. Wait... by the nets.",
                "Eles vêm... quando a névoa fica lilás. Esperem... perto das redes."),

            // ================= Sangkent — Abā, o chefe das calhas =================
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.title", "Stones in the Chutes", "Pedras nas Calhas"),
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.description",
                "Stones dimmed by the cold have come loose from the slopes above Sangkent and roll down the polished chutes on their own, jamming the carts between the terraces. Abā, who keeps every chute of the city running, asked the cousins to break them up before a cart full of people meets one.",
                "Pedras apagadas pelo frio se soltaram das encostas acima de Sangkent e descem sozinhas pelas calhas polidas, travando os carrinhos entre os terraços. O Abā, que mantém todas as calhas da cidade funcionando, pediu aos primos que quebrem as pedras antes que um carrinho cheio de gente encontre uma."),
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.obj_clear_the_chutes", "Break the rolling stones off the chutes", "Quebrar as pedras-rolantes das calhas"),
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.journal",
                "With the last stone in pieces, Abā sent an empty cart down the long chute and listened to it all the way to the market terrace. Not a single bump. Ícaro asked to go down in the next one. Abā said yes, then said no, and then went down with him.",
                "Com a última pedra em pedaços, o Abā mandou um carrinho vazio pela calha comprida e ficou escutando até ele chegar ao terraço do mercado. Nenhum solavanco. O Ícaro pediu para descer no próximo. O Abā disse que sim, depois disse que não, e depois desceu junto com ele."),
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.offer",
                "Edna's grandchildren, on my terraces! Jorge rode my first chute when it was still a plank on the snow. Now seven stones roll down my chutes with nobody in them. Break them before they meet a cart, and the whole city will ride in peace again.",
                "Os netos da Edna, nos meus terraços! O Jorge desceu na minha primeira calha quando ela ainda era uma tábua na neve. Agora sete pedras descem pelas minhas calhas sem ninguém dentro. Quebrem elas antes que encontrem um carrinho, e a cidade inteira vai voltar a descer em paz."),
            new LocalizationEntry("quest.city_sangkent_stones_in_the_chutes.active",
                "A stone that rolls on its own always comes back up for another go. Wait for it at the top of the chute.",
                "Pedra que rola sozinha sempre sobe de novo para mais uma descida. Esperem por ela no alto da calha."),

            // ================= Sangkent — Kustai, o escriba do quadro das caravanas =================
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.title", "Mist on the Board", "Neblina no Quadro"),
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.description",
                "A bad-wind mist has settled over the caravan notice board that Kustai keeps by the plaza: the ink runs, the notices blow away and the caravans no longer know who is going east and who is going west. The scribe asked the cousins to chase it off the terraces.",
                "Uma neblina de vento ruim pousou no quadro de avisos das caravanas que o Kustai cuida perto da praça: a tinta escorre, os avisos voam e as caravanas já não sabem quem vai para o leste e quem vai para o oeste. O escriba pediu aos primos que espantem a neblina dos terraços."),
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.obj_clear_the_board", "Chase the ill-wind mist off the notice board", "Espantar a neblina do vento ruim do quadro de avisos"),
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.journal",
                "Kustai copied every notice again, in his small careful hand, and pinned them up one by one. Maithe read them all aloud for the caravaneers who cannot read. He gave her the storm cloak and said the Wakhan Pass is the only notice that never changes: go in warm.",
                "O Kustai copiou todos os avisos de novo, com a letra pequena e caprichada dele, e pregou um por um. A Maithe leu todos em voz alta para os caravaneiros que não sabem ler. Ele deu a capa de tempestade para ela e disse que o Passo de Wakhan é o único aviso que nunca muda: entre agasalhado."),
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.offer",
                "You cleared Abā's chutes; now my board. Six puffs of bad-wind mist sit on it and the ink runs off every notice. Chase them off and take this storm cloak: up in the Wakhan Pass the wind tears the words out of your mouth.",
                "Vocês limparam as calhas do Abā; agora o meu quadro. Seis nuvens de neblina do vento ruim estão sentadas nele e a tinta escorre de todos os avisos. Espantem elas e levem esta capa de tempestade: lá no Passo de Wakhan o vento arranca as palavras da boca da gente."),
            new LocalizationEntry("quest.city_sangkent_mist_on_the_board.active",
                "The mist hates the dry wind from the valley. Stand with your back to the valley and it comes to you.",
                "A neblina detesta o vento seco do vale. Fiquem de costas para o vale e ela vem até vocês."),

            // ================= Mingcheng — Bögü, o chefe da guarda dos anéis =================
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.title", "Lions at the Gates", "Leões nos Portões"),
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.description",
                "The stone lions that guard the gates of the outer rings have gone dim and walk on their own: they sit in the middle of the arches and nobody gets in or out when the drum calls. Bögü, who has kept the ring guard for longer than anyone remembers, asked the cousins to break the dimmed ones before the bell shuts the gates.",
                "Os leões de pedra que guardam os portões dos anéis de fora se apagaram e andam sozinhos: sentam no meio dos arcos e ninguém entra nem sai quando o tambor chama. O Bögü, que cuida da guarda dos anéis há mais tempo do que alguém lembra, pediu aos primos que quebrem os apagados antes que o sino feche os portões."),
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.obj_clear_the_gates", "Break the dimmed stone lions at the gates", "Quebrar os leões de pedra apagados dos portões"),
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.journal",
                "When the drum sounded at dawn, every gate of the outer rings opened at once, and the farmers came in with their baskets as if nothing had happened. Bögü counted them all, one by one. Joaquim asked if he ever loses count. He said once, the day Edna and Jorge got married, because the whole city came in at the same time.",
                "Quando o tambor tocou de manhã, todos os portões dos anéis de fora abriram de uma vez, e os lavradores entraram com os cestos como se nada tivesse acontecido. O Bögü contou todos, um por um. O Joaquim perguntou se ele já perdeu a conta. Ele disse que uma vez, no dia em que a Edna e o Jorge se casaram, porque a cidade inteira entrou ao mesmo tempo."),
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.offer",
                "Edna's grandchildren, inside my rings! I kept the gate the night your grandpa Jorge arrived late and begged to come in. I let him. Now seven stone lions sit in my arches and nobody passes. Break the dimmed ones before the bell, and the gates will breathe again.",
                "Os netos da Edna, dentro dos meus anéis! Eu guardava o portão na noite em que o seu avô Jorge chegou atrasado e implorou para entrar. Eu deixei. Agora sete leões de pedra estão sentados nos meus arcos e ninguém passa. Quebrem os apagados antes do sino, e os portões vão respirar de novo."),
            new LocalizationEntry("quest.city_mingcheng_lions_at_the_gates.active",
                "A dim lion is heavy and slow. Hit it from the side, never from the front: it only looks ahead.",
                "Leão apagado é pesado e lento. Batam de lado, nunca de frente: ele só olha para a frente."),

            // ================= Mingcheng — Lin Deng, o mestre do canal =================
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.title", "Fish in the Canal", "Peixes no Canal"),
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.description",
                "Lantern fish have come up the canal from the south and swim in a crowd under the humpback bridges: their light blinks out of time, and the barges that carry the crafts between the rings bump into the locks in the dark. Lin Deng, who keeps the canal, asked the cousins to chase them out.",
                "Peixes-lanterna subiram o canal vindos do sul e nadam em bando debaixo das pontes de corcunda: a luz deles pisca fora de hora, e as barcas que levam os ofícios entre os anéis batem nas eclusas no escuro. O Lin Deng, que cuida do canal, pediu aos primos que espantem os peixes."),
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.obj_clear_the_canal", "Chase the lantern fish out of the canal", "Espantar os peixes-lanterna do canal"),
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.journal",
                "Lin Deng sent the first barge of the night through the lock and it slid by without a bump. Maria counted the lanterns along the canal and wrote the number down. He gave the cousins the Sun Seal and said the White Spires open their gate only for whoever carries the light of the city in their pocket.",
                "O Lin Deng mandou a primeira barca da noite pela eclusa e ela passou sem um solavanco. A Maria contou as lanternas ao longo do canal e anotou o número. Ele deu aos primos o Selo do Sol e disse que as Torres Brancas só abrem o portão para quem leva a luz da cidade no bolso."),
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.offer",
                "You opened Bögü's gates; now my canal. Six lantern fish blink under my bridges and the barges get lost between the locks. Chase them out and the Sun Seal is yours: without it the White Spires will not even look at you.",
                "Vocês abriram os portões do Bögü; agora o meu canal. Seis peixes-lanterna piscam debaixo das minhas pontes e as barcas se perdem entre as eclusas. Espantem eles e o Selo do Sol é de vocês: sem ele as Torres Brancas nem olham para vocês."),
            new LocalizationEntry("quest.city_mingcheng_fish_in_the_canal.active",
                "They blink when the water is still. Wait on the bridge until the canal goes quiet.",
                "Eles piscam quando a água para. Esperem em cima da ponte até o canal ficar quieto."),

            // ================= Torres Brancas — Amanirenas, a rainha-guardiã =================
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.title", "Broken Mirrors", "Espelhos Quebrados"),
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.description",
                "Some of the mirrors that pass the sunlight down from the white spires have cracked and dimmed, and now they move on their own, throwing the light back into the sky instead of down to the gardens. Queen Amanirenas asked the cousins to break the dimmed ones so the towers can be fitted with new glass.",
                "Alguns dos espelhos que passam a luz do sol das torres brancas até o chão racharam e se apagaram, e agora andam sozinhos, jogando a luz de volta para o céu em vez de para os jardins. A rainha Amanirenas pediu aos primos que quebrem os apagados para as torres ganharem vidro novo."),
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.obj_break_the_mirrors", "Break the dimmed mirrors of the towers", "Quebrar os espelhos apagados das torres"),
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.journal",
                "With the dim mirrors gone, Amanitore set new glass in every tower before sunset, and the light came down to the gardens again. Lavine lay on the grass under the beam of the tallest spire. Amanirenas said Grandma Edna used to do the same, and that the queen of that time let her.",
                "Sem os espelhos apagados, a Amanitore pôs vidro novo em todas as torres antes do pôr do sol, e a luz voltou a descer até os jardins. A Lavine deitou na grama debaixo do raio da torre mais alta. A Amanirenas disse que a Vó Edna fazia a mesma coisa, e que a rainha daquela época deixava."),
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.offer",
                "You carry the Sun Seal, so Mingcheng trusts you. So do I. Seven mirrors of my towers have cracked and dimmed and now walk the terraces, throwing our light back at the sky. Break them, gently if you can, and the gardens will have their sun again.",
                "Vocês levam o Selo do Sol, então Mingcheng confia em vocês. Eu também. Sete espelhos das minhas torres racharam, se apagaram e agora andam pelos terraços, jogando a nossa luz de volta para o céu. Quebrem eles, com cuidado se der, e os jardins vão ter o sol de novo."),
            new LocalizationEntry("quest.city_torres_brancas_broken_mirrors.active",
                "A broken mirror shows you your own back. Do not look into it for long: strike and turn away.",
                "Espelho quebrado mostra as suas próprias costas. Não olhem muito tempo: batam e virem o rosto."),

            // ================= Torres Brancas — Shanakdakhete, a que ensina a luz =================
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.title", "The Dimmed Ibises", "As Íbis Apagadas"),
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.description",
                "The white ibises that wade in the garden rills have gone dark, and now they peck at the beams of light the mirrors pass down, breaking them into pieces before they reach the ground. Shanakdakhete, who teaches the light to the young elves, asked the cousins to chase them off the terraces.",
                "As íbis brancas que andam nos riachos dos jardins escureceram, e agora bicam os raios de luz que os espelhos passam para baixo, quebrando a luz em pedaços antes que ela chegue ao chão. A Shanakdakhete, que ensina a luz aos elfos jovens, pediu aos primos que espantem as íbis dos terraços."),
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.obj_chase_the_ibises", "Chase the dimmed ibises off the terraces", "Espantar as íbis apagadas dos terraços"),
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.journal",
                "The beams came down whole again, and Shanakdakhete's students cheered from the leaf bridges. Ícaro asked if he could catch a beam in a jar. She gave him a rune lamp instead, and two soul stones for the forge, and said a beam in a jar is just a lamp that forgot it was free.",
                "Os raios voltaram a descer inteiros, e os alunos da Shanakdakhete comemoraram nas pontes de folha. O Ícaro perguntou se podia pegar um raio num pote. Ela deu a ele uma lamparina rúnica, e duas pedras da alma para a forja, e disse que raio num pote é só uma lâmpada que esqueceu que era livre."),
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.offer",
                "The queen's mirrors are whole again; now my beams. Six dimmed ibises peck the light to pieces before it touches the gardens. Chase them off, and I will give you a lamp that never forgets its rune.",
                "Os espelhos da rainha estão inteiros de novo; agora os meus raios. Seis íbis apagadas bicam a luz em pedaços antes que ela toque os jardins. Espantem elas, e eu dou a vocês uma lamparina que nunca esquece a sua runa."),
            new LocalizationEntry("quest.city_torres_brancas_dimmed_ibises.active",
                "They come to the brightest beam. Stand where the light falls and wait.",
                "Elas vêm para o raio mais forte. Fiquem onde a luz cai e esperem."),

            // ================= Acampamento de Soslan — Soslan, o de Pele de Aço =================
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.title", "Wolves Round the Foals", "Lobos em Volta dos Potros"),
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.description",
                "Wolves dimmed by the shadow circle the camp at dusk, closer every night, and the foals no longer sleep. Soslan, who has never lost a foal, asked the cousins to chase the pack back into the tall grass before the camp moves on.",
                "Lobos apagados pela sombra rondam o acampamento ao entardecer, cada noite mais perto, e os potros já não dormem. O Soslan, que nunca perdeu um potro, pediu aos primos que espantem a matilha de volta para o capim alto antes que o acampamento mude de lugar."),
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.obj_chase_the_wolves", "Chase the dimmed wolves away from the foals", "Espantar os lobos apagados de perto dos potros"),
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.journal",
                "With the last wolf gone into the grass, the foals lay down in a ring and slept at once. Soslan counted them twice, then a third time, and laughed so loud that two of them woke up again. Joaquim helped him count the fourth time.",
                "Com o último lobo sumido no capim, os potros deitaram em roda e dormiram na hora. O Soslan contou todos duas vezes, depois uma terceira, e riu tão alto que dois acordaram de novo. O Joaquim ajudou a contar a quarta vez."),
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.offer",
                "Edna's grandchildren, in my camp! Jorge raced me once across the whole steppe and lost by a nose. Mine. Now eight dimmed wolves circle my foals every night. Chase them back into the grass and the camp can move on in peace.",
                "Os netos da Edna, no meu acampamento! O Jorge apostou corrida comigo uma vez pela estepe inteira e perdeu por um focinho. O meu. Agora oito lobos apagados rondam os meus potros toda noite. Espantem eles de volta para o capim e o acampamento pode seguir em paz."),
            new LocalizationEntry("quest.city_soslan_wolves_round_the_foals.active",
                "They come with the wind at their backs. Stand downwind of the foals and they walk straight to you.",
                "Eles vêm com o vento nas costas. Fiquem do lado de onde o vento sopra e eles caminham direto até vocês."),

            // ================= Acampamento de Soslan — Satana, a Sábia da Casa =================
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.title", "Eagles over the Camp", "Águias sobre o Acampamento"),
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.description",
                "Golden eagles dimmed by the shadow circle over the felt tents and dive at the guardian lamp that Satana keeps lit at the heart of the camp. The wise woman asked the cousins to chase them back to the high rocks before the lamp goes out.",
                "Águias-douradas apagadas pela sombra rodam sobre as tendas de feltro e mergulham na lâmpada guardiã que a Satana mantém acesa no meio do acampamento. A sábia pediu aos primos que espantem as águias de volta para as pedras altas antes que a lâmpada se apague."),
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.obj_chase_the_eagles", "Chase the dimmed eagles away from the guardian lamp", "Espantar as águias apagadas de perto da lâmpada guardiã"),
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.journal",
                "The lamp burned steady again and Satana trimmed its wick with two fingers, without burning them. She gave Maithe a rune lamp of her own and said the eldest carries the light at the front of the wagons. Ícaro asked who carries it at the back. 'You,' she said, 'once you stop running.'",
                "A lâmpada voltou a queimar firme e a Satana aparou o pavio com dois dedos, sem se queimar. Ela deu uma lamparina rúnica para a Maithe e disse que a mais velha leva a luz na frente das carroças. O Ícaro perguntou quem leva atrás. 'Você', ela disse, 'quando parar de correr.'"),
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.offer",
                "You kept Soslan's foals; now keep my lamp. Six dimmed eagles dive at it every day, and a camp that moves needs a light that does not. Chase them off and take a lamp of your own: the steppe is dark between two camps.",
                "Vocês guardaram os potros do Soslan; agora guardem a minha lâmpada. Seis águias apagadas mergulham nela todo dia, e um acampamento que anda precisa de uma luz que não anda. Espantem elas e levem uma lamparina para vocês: a estepe é escura entre dois acampamentos."),
            new LocalizationEntry("quest.city_soslan_eagles_over_the_camp.active",
                "An eagle hates a shadow it cannot see. Stand in the open, far from the tents, and let it dive at you.",
                "Águia detesta sombra que não enxerga. Fiquem no aberto, longe das tendas, e deixem ela mergulhar em vocês."),

            // ================= Fortim dos Gigantes — Baraqel, o Chefe do Fortim =================
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.title", "Boars in the Pantry", "Javalis na Despensa"),
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.description",
                "Hill boars dimmed by the shadow dig under the earth ramparts every night and eat the giants' turnips, roots and all. Baraqel, who will not hurt even a boar, asked the cousins to chase them back down the hill before the pantry is empty and the Panela Grande goes cold.",
                "Javalis da colina apagados pela sombra cavam por baixo das muralhas de terra toda noite e comem os nabos dos gigantes, com raiz e tudo. O Baraqel, que não machuca nem javali, pediu aos primos que espantem os bichos morro abaixo antes que a despensa fique vazia e a Panela Grande esfrie."),
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.obj_chase_the_boars", "Chase the dimmed boars out of the pantry", "Espantar os javalis apagados da despensa"),
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.journal",
                "Baraqel filled the pantry again with turnips the size of a cousin and sat the five of them on a spoon to watch the boars run downhill. Maria counted the turnips. Baraqel let her count them all, every single one, and then asked her to count them again.",
                "O Baraqel encheu a despensa de novo com nabos do tamanho de um primo e sentou os cinco numa colher para ver os javalis correndo morro abaixo. A Maria contou os nabos. O Baraqel deixou ela contar todos, cada um, e depois pediu para contar de novo."),
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.offer",
                "Little ones! Edna's grandchildren, on my hill! Jorge sat on that very spoon forty years ago and fell asleep before the soup. Now seven dimmed boars dig under my ramparts. I cannot shout at a boar, it is too small. You can. Chase them away for me.",
                "Pequenos! Os netos da Edna, no meu morro! O Jorge sentou nessa mesma colher há quarenta anos e dormiu antes da sopa. Agora sete javalis apagados cavam por baixo das minhas muralhas. Eu não consigo gritar com um javali, ele é pequeno demais. Vocês conseguem. Espantem eles para mim."),
            new LocalizationEntry("quest.city_fortim_boars_in_the_pantry.active",
                "They dig where the earth is soft, by the turnips. Wait there; they always come back for one more.",
                "Eles cavam onde a terra é mole, perto dos nabos. Esperem ali; eles sempre voltam para mais um."),

            // ================= Fortim dos Gigantes — Virogdad, o Sonhador =================
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.title", "Crows of a Bad Dream", "Os Corvos do Sonho Ruim"),
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.description",
                "Virogdad dreamt of smoke crows and woke up to find them real, perched on the clay tablets where he writes the dreams of the giants. Every crow pecks out one good word. The dreamer asked the cousins to chase them off the tablets before the dreams turn bad.",
                "O Virogdad sonhou com corvos de fumaça e acordou com eles de verdade, pousados nas tábuas de barro onde ele escreve os sonhos dos gigantes. Cada corvo bica uma palavra boa. O sonhador pediu aos primos que espantem os corvos das tábuas antes que os sonhos fiquem ruins."),
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.obj_chase_the_crows", "Chase the smoke crows off the dream tablets", "Espantar os corvos de fumaça das tábuas de sonho"),
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.journal",
                "Virogdad wrote the pecked words back in, one by one, with a finger as wide as a brush. He read the last dream aloud: a chain on a mountain and someone who wants to come down. Then he gave Lavine a pair of crampons and said that is where the dream goes next.",
                "O Virogdad escreveu de volta as palavras bicadas, uma por uma, com um dedo da largura de um pincel. Leu o último sonho em voz alta: uma corrente numa montanha e alguém que quer descer. Depois deu um par de grampos para a Lavine e disse que é para lá que o sonho vai agora."),
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.offer",
                "You saved Baraqel's turnips; now save my dreams. Six smoke crows sit on my tablets and eat the good words. Chase them off and take these crampons: the dream of the chain on the mountain is for small feet.",
                "Vocês salvaram os nabos do Baraqel; agora salvem os meus sonhos. Seis corvos de fumaça estão sentados nas minhas tábuas comendo as palavras boas. Espantem eles e levem estes grampos: o sonho da corrente na montanha é para pés pequenos."),
            new LocalizationEntry("quest.city_fortim_crows_of_a_bad_dream.active",
                "Crows of a dream come back when you look away. Keep your eyes on the tablets.",
                "Corvo de sonho volta quando a gente olha para o outro lado. Fiquem de olho nas tábuas."),

            // ================= Arvoredo de Haripushpa — Haripushpa, o Mais Velho =================
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.title", "The Bark-Eaters", "Os Comedores de Casca"),
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.description",
                "Bark-eaters dimmed by the shadow crawl over the trunk folk who sleep in the ring of the grove and chew their bark while they dream. Old Haripushpa, who speaks one sentence a minute, took three minutes to ask the cousins to clear them off the sleepers.",
                "Comedores de casca apagados pela sombra sobem pelo povo-tronco que dorme no círculo do arvoredo e mastigam a casca deles enquanto sonham. O velho Haripushpa, que fala uma frase por minuto, levou três minutos para pedir aos primos que tirem os bichos de cima dos que dormem."),
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.obj_clear_the_bark", "Clear the bark-eaters off the sleeping trunks", "Tirar os comedores de casca dos troncos que dormem"),
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.journal",
                "Haripushpa waited until the last bark-eater was gone, then waited a little more, and then said thank you. It took the whole afternoon. Ícaro waited with him the whole time and did not run once. Haripushpa says it is the first time a cousin has done that.",
                "O Haripushpa esperou até o último comedor de casca sumir, depois esperou mais um pouco, e então disse obrigado. Levou a tarde inteira. O Ícaro esperou com ele o tempo todo sem correr nenhuma vez. O Haripushpa diz que é a primeira vez que um primo faz isso."),
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.offer",
                "Little ones... Edna's... grandchildren. Jorge... sat by me... one whole summer. Seven bark-eaters... chew... my sleeping neighbours. Clear them... please. ...I am not finished. ...There. Now I am.",
                "Pequenos... netos... da Edna. O Jorge... sentou do meu lado... um verão inteiro. Sete comedores de casca... mastigam... os meus vizinhos que dormem. Tirem eles... por favor. ...Eu não terminei. ...Pronto. Agora terminei."),
            new LocalizationEntry("quest.city_arvoredo_bark_eaters.active",
                "They like... the old bark. Look... at the oldest trunks.",
                "Eles gostam... da casca velha. Procurem... nos troncos mais velhos."),

            // ================= Arvoredo de Haripushpa — Aryaman Puhr, o Herbolário =================
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.title", "Smoke Birds", "Os Pássaros de Fumaça"),
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.description",
                "Birds of smoke peck holes in the trunks of the grove, and through every hole the Living Water of the thaw runs out of the sleepers. Aryaman Puhr, the Sogdian herbalist who comes every spring for the herbs, asked the cousins to chase them out before the trunks dry up.",
                "Pássaros de fumaça bicam buracos nos troncos do arvoredo, e por cada buraco a Água Viva do degelo escorre dos que dormem. O Aryaman Puhr, o herbolário sogdiano que vem toda primavera buscar ervas, pediu aos primos que espantem os pássaros antes que os troncos sequem."),
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.obj_chase_the_smoke_birds", "Chase the smoke birds out of the grove", "Espantar os pássaros de fumaça do arvoredo"),
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.journal",
                "Aryaman closed every hole with resin and moss, and the trunks drank the meltwater again. He gave Maria three healing runes and showed her how the grove heals: slowly, from the inside, the way a letter arrives from very far away.",
                "O Aryaman fechou todos os buracos com resina e musgo, e os troncos voltaram a beber a água do degelo. Ele deu três runas de cura para a Maria e mostrou como o arvoredo se cura: devagar, por dentro, do jeito que chega uma carta de muito longe."),
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.offer",
                "You cleared Haripushpa's sleepers; the old one told me, it took him all morning. Now six smoke birds peck holes in the trunks and the water runs out. Chase them off and I will give you the runes I make from the sap.",
                "Vocês limparam os que dormem do Haripushpa; o velho me contou, levou a manhã inteira. Agora seis pássaros de fumaça bicam buracos nos troncos e a água escorre. Espantem eles e eu dou para vocês as runas que eu faço com a seiva."),
            new LocalizationEntry("quest.city_arvoredo_smoke_birds.active",
                "They peck where the bark is wet. Wait by the stream; the smoke always comes down to drink.",
                "Eles bicam onde a casca está molhada. Esperem perto do riacho; a fumaça sempre desce para beber."),

            // ================= Vale dos Sátiros — Midas, o Rei de Mãos Douradas =================
            new LocalizationEntry("quest.city_vale_golden_bees.title", "The Golden Bees", "As Abelhas de Ouro"),
            new LocalizationEntry("quest.city_vale_golden_bees.description",
                "When Āz touched King Midas, everything his hands held turned to gold, the bees of his hives too. Now they fly golden and angry over the river, and whoever they sting goes slow and stiff with gold. Midas cannot wash his hands in the Living Water while they guard it; he asked the cousins to chase them back to the hives.",
                "Quando Āz tocou o rei Midas, tudo o que as mãos dele seguravam virou ouro, até as abelhas das colmeias dele. Agora elas voam douradas e bravas sobre o rio, e quem elas picam fica lento e duro de ouro. O Midas não consegue lavar as mãos na Água Viva enquanto elas guardam o rio; pediu aos primos que espantem as abelhas de volta para as colmeias."),
            new LocalizationEntry("quest.city_vale_golden_bees.obj_chase_the_bees", "Chase the golden bees away from the river", "Espantar as abelhas de ouro de perto do rio"),
            new LocalizationEntry("quest.city_vale_golden_bees.journal",
                "With the river free, Midas knelt and washed his hands until the gold ran off them like sand and settled among the pebbles. He picked up a grape and it stayed a grape. He laughed and ate it, and then he cried a little, and Maria held the bunch for him while he did.",
                "Com o rio livre, o Midas ajoelhou e lavou as mãos até o ouro escorrer delas como areia e assentar entre os seixos. Ele pegou uma uva e ela continuou uva. Ele riu e comeu, e depois chorou um pouco, e a Maria segurou o cacho para ele enquanto isso."),
            new LocalizationEntry("quest.city_vale_golden_bees.offer",
                "Edna's grandchildren! Do not shake my hand, little ones, unless you want to be a statue. Your grandpa Jorge did, once, and stood golden by the river for an afternoon until the water took it off. Eight golden bees guard the river now, and I cannot wash. Chase them home and I will be a king again, not a goldsmith.",
                "Os netos da Edna! Não apertem a minha mão, pequenos, a não ser que queiram virar estátua. O vô Jorge de vocês apertou, uma vez, e ficou dourado na beira do rio uma tarde inteira até a água tirar. Oito abelhas de ouro guardam o rio agora, e eu não consigo me lavar. Espantem elas para casa e eu volto a ser rei, não ourives."),
            new LocalizationEntry("quest.city_vale_golden_bees.active",
                "If one stings you and you go stiff, run to the river and wash. The Living Water takes the gold off.",
                "Se uma picar vocês e vocês ficarem duros, corram para o rio e se lavem. A Água Viva tira o ouro."),

            // ================= Vale dos Sátiros — Gordias, o Fazendeiro dos Nós =================
            new LocalizationEntry("quest.city_vale_vine_foxes.title", "Foxes in the Vines", "Raposas na Vinha"),
            new LocalizationEntry("quest.city_vale_vine_foxes.description",
                "The foxes of the vineyard, dimmed by the shadow, slip between the rows at night and chew through the knots Gordias ties to hold the vines up. The farmer of the knots can tie anything, but not faster than seven foxes can bite. He asked the cousins to chase them back up the slope.",
                "As raposas da vinha, apagadas pela sombra, se enfiam entre as fileiras de noite e roem os nós que o Gordias amarra para segurar as videiras. O fazendeiro dos nós amarra qualquer coisa, mas não mais rápido que sete raposas roendo. Ele pediu aos primos que espantem as raposas de volta para a encosta."),
            new LocalizationEntry("quest.city_vale_vine_foxes.obj_chase_the_foxes", "Chase the vine foxes out of the rows", "Espantar as raposas das fileiras da vinha"),
            new LocalizationEntry("quest.city_vale_vine_foxes.journal",
                "Gordias retied every knot in one evening, humming. Then he tied one more, a knot nobody could open, and gave it to Ícaro. Ícaro spent the whole walk back trying. Gordias says that is the point: a knot that keeps a boy patient for an hour is worth more than gold.",
                "O Gordias refez todos os nós numa noite, cantarolando. Depois amarrou mais um, um nó que ninguém abria, e deu para o Ícaro. O Ícaro passou a volta inteira tentando. O Gordias diz que a graça é essa: um nó que deixa um menino paciente por uma hora vale mais que ouro."),
            new LocalizationEntry("quest.city_vale_vine_foxes.offer",
                "Ah, the cousins who freed the river! Then you are good with your hands. I tie the vines, seven foxes untie them with their teeth. Your grandma Edna once tied a knot here that I still cannot undo, she was that good. Chase the foxes away and I will pay you with wind songs, the runes Marsyas likes.",
                "Ah, os primos que libertaram o rio! Então vocês são bons de mão. Eu amarro as videiras, sete raposas desamarram com os dentes. A vó Edna de vocês uma vez deu um nó aqui que eu até hoje não consigo desfazer, de tão boa que ela era. Espantem as raposas e eu pago com canções de vento, as runas que o Marsyas gosta."),
            new LocalizationEntry("quest.city_vale_vine_foxes.active",
                "They come in at dusk from the slope, when the dance starts and nobody watches the rows.",
                "Elas descem da encosta ao entardecer, quando o baile começa e ninguém olha as fileiras."),

            // ================= Farnkesh — Shad-Ohrmizd, o Guardião dos Sinos =================
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.title", "Vultures on the Bells", "Abutres nos Sinos"),
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.description",
                "Peak vultures dimmed by the shadow perch on the wind bells of the pinnacles and hold them still with their weight. A bell that does not ring lets the ill wind in. Shad-Ohrmizd, who keeps every bell of Farnkesh, asked the cousins to chase them off the frames.",
                "Abutres do pico apagados pela sombra pousam nos sinos de vento dos pináculos e seguram eles parados com o peso. Sino que não toca deixa o vento ruim entrar. O Shad-Ohrmizd, que cuida de todos os sinos de Farnkesh, pediu aos primos que espantem os abutres das armações."),
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.obj_chase_the_vultures", "Chase the peak vultures off the wind bells", "Espantar os abutres do pico dos sinos de vento"),
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.journal",
                "When the last vulture let go, all the bells of Farnkesh rang at once, from the big one on the plaza to the smallest chime on a balcony. Maithe stood still and listened with her eyes closed. Shad-Ohrmizd says she heard the Living Wind say her name. Maithe says she only heard bells. Nobody believes her.",
                "Quando o último abutre soltou, todos os sinos de Farnkesh tocaram de uma vez, do grande da praça ao sininho mais pequeno de uma varanda. A Maithe ficou parada escutando de olhos fechados. O Shad-Ohrmizd diz que ela ouviu o Vento Vivo dizer o nome dela. A Maithe diz que só ouviu sinos. Ninguém acredita."),
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.offer",
                "Edna's grandchildren, up here above the clouds! Your grandpa Jorge climbed the baskets once and said he would never do it again; then he did it every summer. Seven peak vultures sit on my bells and the bells keep quiet. A quiet bell is a door left open to the ill wind. Chase them off, please.",
                "Os netos da Edna, aqui em cima das nuvens! O vô Jorge de vocês subiu nos cestos uma vez e disse que nunca mais; depois subiu todo verão. Sete abutres do pico sentam nos meus sinos e os sinos ficam quietos. Sino quieto é porta aberta para o vento ruim. Espantem eles, por favor."),
            new LocalizationEntry("quest.city_farnkesh_vultures_on_the_bells.active",
                "They like the bells on the outer pinnacles, where the wind is strongest. Listen for the ones that do not ring.",
                "Eles gostam dos sinos dos pináculos de fora, onde o vento é mais forte. Escutem quais não tocam."),

            // ================= Farnkesh — Tadi, a Dobradora de Papel de Vento =================
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.title", "Ill Wind on the Bridges", "Vento Ruim nas Pontes"),
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.description",
                "A mist of the ill wind has settled on the rope bridges between the pinnacles: it tears Tadi's wind paper, blinds whoever crosses and makes the ropes sway. Tadi asked the cousins to blow it apart, and promised them a storm cloak for the Garganta dos Ays.",
                "Uma neblina de vento ruim pousou nas pontes de corda entre os pináculos: rasga o papel de vento da Tadi, cega quem atravessa e faz as cordas balançarem. A Tadi pediu aos primos que desmanchem a neblina, e prometeu uma capa de tempestade para a Garganta dos Ays."),
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.obj_clear_the_mist", "Clear the mist of the ill wind off the rope bridges", "Desmanchar a neblina de vento ruim das pontes de corda"),
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.journal",
                "With the mist gone, Tadi let a sheet of wind paper go from the highest bridge. It flew all the way down to the Vale, turning, and a satyr down there caught it and waved. Lavine waved back. Tadi gave the cousins the storm cloak she had sewn from old kite cloth: it does not tear.",
                "Com a neblina embora, a Tadi soltou uma folha de papel de vento da ponte mais alta. Ela voou até lá embaixo no Vale, girando, e um sátiro pegou e acenou. A Lavine acenou de volta. A Tadi deu aos primos a capa de tempestade que ela costurou com pano velho de pipa: não rasga."),
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.offer",
                "You chased the vultures? Then the bells are ringing and I can hear myself think. My sister Nafsha says hello, she says she met you down below. Six patches of ill-wind mist sit on my bridges and tear every paper I fold. Blow them apart and I will give you a cloak the storm cannot tear: you will need it in the gorge.",
                "Vocês espantaram os abutres? Então os sinos estão tocando e eu consigo pensar. A minha irmã Nafsha manda um oi, diz que conheceu vocês lá embaixo. Seis manchas de neblina de vento ruim estão nas minhas pontes e rasgam todo papel que eu dobro. Desmanchem elas e eu dou uma capa que a tempestade não rasga: vão precisar dela na garganta."),
            new LocalizationEntry("quest.city_farnkesh_ill_wind_on_the_bridges.active",
                "Hold the rope when the gust comes. The mist hides in the middle of the bridges, where the planks shake most.",
                "Segurem a corda quando vier a rajada. A neblina se esconde no meio das pontes, onde as tábuas balançam mais."),

            // ================= Porto da Lua Branca — Yirkap, o Caçador de Esqui =================
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.title", "Gulls on the Racks", "Gaivotas nos Varais"),
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.description",
                "Gulls dimmed by the shadow have learned to steal: they dive on the fish racks of the quays, tear the silver fish down and scream at whoever comes near. The fishing quarter will have nothing to eat when the polar night comes. Yirkap, who hunts on skis faster than the reindeer run, asked the cousins to chase them off the racks.",
                "Gaivotas apagadas pela sombra aprenderam a roubar: mergulham nos varais de peixe do cais, arrancam os peixes de prata e gritam com quem chega perto. O bairro de pesca vai ficar sem comida quando vier a noite polar. O Yirkap, que caça de esqui mais rápido que as renas correm, pediu aos primos que espantem as gaivotas dos varais."),
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.obj_chase_the_gulls", "Chase the thieving gulls off the fish racks", "Espantar as gaivotas ladras dos varais de peixe"),
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.journal",
                "With the gulls gone, the fishing quarter hung its fish again and Yirkap lent Joaquim his skis for one run across the bay. Joaquim fell four times and got up five. Yirkap says that is how every ski hunter starts, and that the fifth time is the one that counts.",
                "Com as gaivotas embora, o bairro de pesca pendurou os peixes de novo e o Yirkap emprestou os esquis para o Joaquim dar uma volta na baía. O Joaquim caiu quatro vezes e levantou cinco. O Yirkap diz que é assim que todo caçador de esqui começa, e que a quinta vez é a que conta."),
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.offer",
                "Edna's grandchildren, this far north! Your grandpa Jorge came up here once to see the Moon Ship and stayed a whole winter because the canals froze. Eight gulls of the shadow are stealing the fish off our racks. I am fast on skis, but a gull is faster in the air. Chase them off, and the quarter eats this winter.",
                "Os netos da Edna, aqui no norte! O vô Jorge de vocês subiu até aqui uma vez para ver a Barca da Lua e ficou o inverno inteiro porque os canais congelaram. Oito gaivotas da sombra estão roubando o peixe dos nossos varais. Eu sou rápido no esqui, mas gaivota é mais rápida no ar. Espantem elas, e o bairro come neste inverno."),
            new LocalizationEntry("quest.city_porto_gulls_on_the_racks.active",
                "They come in low over the canals at dusk, when the lanterns are lit and the fishers go home.",
                "Elas chegam baixinho por cima dos canais ao entardecer, quando as lanternas acendem e os pescadores vão para casa."),

            // ================= Porto da Lua Branca — Pera, o Gigante Bom =================
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.title", "Bears on the Canals", "Ursos nos Canais"),
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.description",
                "Bears dimmed by the shadow have come down onto the ice of the canals and will not let anyone pass: not the boats, not Pera, who breaks the ice every morning so the crescent boats can go out. A giant can break ice, but he does not like to fight. Pera asked the cousins to chase the bears back to the open tundra, and promised them a suit of thermal furs for the cold beyond the harbour.",
                "Ursos apagados pela sombra desceram para o gelo dos canais e não deixam ninguém passar: nem os barcos, nem o Pera, que quebra o gelo toda manhã para os barcos em meia-lua saírem. Gigante quebra gelo, mas não gosta de briga. O Pera pediu aos primos que espantem os ursos de volta para a tundra aberta, e prometeu uma roupa térmica de pele para o frio depois do porto."),
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.obj_chase_the_bears", "Chase the dimmed bears off the ice of the canals", "Espantar os ursos apagados do gelo dos canais"),
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.journal",
                "With the bears gone, Pera broke the ice of the whole canal in one morning, singing, and the crescent boats went out in a line like a necklace. Ícaro rode on his shoulder the whole way. Pera gave the cousins the thermal furs his mother sewed for him when he was small: they fit Maithe perfectly.",
                "Com os ursos embora, o Pera quebrou o gelo do canal inteiro numa manhã, cantando, e os barcos em meia-lua saíram em fila como um colar. O Ícaro foi no ombro dele o caminho todo. O Pera deu aos primos a roupa térmica que a mãe dele costurou quando ele era pequeno: serviu certinho na Maithe."),
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.offer",
                "Ah, the little ones who chased the gulls! Good, good. I am Pera. I am big, yes, do not worry, I only break ice. Six bears of the shadow sit on my canals and growl at the boats. Your grandma Edna once scolded a bear off this very quay with a ladle; I cannot do it like her. Chase them away and I will give you furs that keep the polar night out.",
                "Ah, os pequenos que espantaram as gaivotas! Bom, bom. Eu sou o Pera. Sou grande, sim, não se preocupem, eu só quebro gelo. Seis ursos da sombra sentaram nos meus canais e rosnam para os barcos. A vó Edna de vocês uma vez espantou um urso deste mesmo cais com uma concha de sopa; eu não consigo fazer igual a ela. Espantem eles e eu dou uma pele que deixa a noite polar do lado de fora."),
            new LocalizationEntry("quest.city_porto_bears_on_the_canals.active",
                "They lie on the thin ice by the bridges, where the water is close and the fish come up.",
                "Eles deitam no gelo fino perto das pontes, onde a água está perto e os peixes sobem."),

            // ================= Hinokura — Mestra Akane, a Mestra da Laca =================
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.title", "Crabs on the Racks", "Caranguejos nos Varais"),
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.description",
                "Crabs dimmed by the shadow climb out of the warm shallows of the harbour every evening and up the drying racks of the forge quarter, where the lacquered boards wait for their ninth coat. Their claws scratch the red, and a scratched coat must be sanded down to the wood. Mestra Akane, who lacquers the halls of Hinokura, asked the cousins to chase the crabs back to the sea.",
                "Caranguejos apagados pela sombra sobem toda tarde do raso quente do porto e escalam os varais de secagem do bairro das forjas, onde as tábuas laqueadas esperam a nona demão. As garras riscam o vermelho, e demão riscada tem que ser lixada até a madeira. A Mestra Akane, que laqueia os salões de Hinokura, pediu aos primos que espantem os caranguejos de volta para o mar."),
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.obj_chase_the_crabs", "Chase the volcano crabs off the lacquer racks", "Espantar os caranguejos-vulcão dos varais de laca"),
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.journal",
                "With the crabs gone, the boards got their ninth coat and Mestra Akane let Maria brush one stroke on the door of her hall. It dried a little crooked. Akane says she will leave it like that: a hall with one crooked stroke remembers who helped build it.",
                "Com os caranguejos embora, as tábuas ganharam a nona demão e a Mestra Akane deixou a Maria passar uma pincelada na porta do salão dela. Secou um pouquinho torta. A Akane diz que vai deixar assim: salão com uma pincelada torta lembra quem ajudou a fazer."),
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.offer",
                "Edna's grandchildren, on the Forge Isle! Your grandpa Jorge brought me a radio to fix once, and stayed to watch the lacquer dry; he said it was slower than his rice. Eight crabs of the shadow are scratching my racks every evening. Lacquer forgives nothing. Chase them back to the sea before the ninth coat.",
                "Os netos da Edna, na Ilha-Forja! O vô Jorge de vocês trouxe um rádio para eu consertar uma vez, e ficou olhando a laca secar; disse que era mais demorado que o arroz dele. Oito caranguejos da sombra estão riscando os meus varais toda tarde. Laca não perdoa nada. Espantem eles de volta para o mar antes da nona demão."),
            new LocalizationEntry("quest.city_hinokura_crabs_on_the_racks.active",
                "They come up from the warm shallows when the lava channels glow brightest, at dusk.",
                "Eles sobem do raso quente quando os canais de lava brilham mais, ao entardecer."),

            // ================= Hinokura — Sango, a Barqueira =================
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.title", "Gulls on the Lighthouse Boat", "Gaivotas no Barco-Farol"),
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.description",
                "Gulls of ember, dimmed by the shadow, nest on the lamp of the Barco-Farol and peck at its glass: when the lamp goes dark, the boats lose their way among the black islets of the obsidian reef. Sango, the boatwoman who rows the lighthouse boat out every night, asked the cousins to chase the gulls off, and promised them a boat of their own for the hot channels.",
                "Gaivotas de brasa, apagadas pela sombra, fazem ninho na lâmpada do Barco-Farol e bicam o vidro: quando a lâmpada apaga, os barcos se perdem entre as ilhotas pretas do recife de obsidiana. A Sango, a barqueira que rema o barco-farol toda noite, pediu aos primos que espantem as gaivotas, e prometeu um barco só deles para os canais quentes."),
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.obj_chase_the_gulls", "Chase the ember gulls off the Barco-Farol", "Espantar as gaivotas-brasa do Barco-Farol"),
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.journal",
                "With the gulls gone, the lamp of the Barco-Farol shone all night and Sango let Ícaro hold the oar on the way back. He rowed in a circle twice. Sango laughed, gave the cousins a reed boat tarred against the heat and said that a circle is also a way home, if you are patient.",
                "Com as gaivotas embora, a lâmpada do Barco-Farol brilhou a noite inteira e a Sango deixou o Ícaro segurar o remo na volta. Ele remou em círculo duas vezes. A Sango riu, deu aos primos um barco de junco untado de piche contra o calor e disse que círculo também é caminho de casa, se a gente tiver paciência."),
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.offer",
                "You are the ones who chased Akane's crabs! Good. I am Sango; I row the lighthouse boat. Six gulls of ember sit on my lamp and peck the glass, and without the light the boats hit the obsidian. Your grandma Edna once rowed with me to the reef and sang the whole way so I would not be afraid. Chase the gulls, and I will give you a boat that does not burn.",
                "Vocês são os que espantaram os caranguejos da Akane! Bom. Eu sou a Sango; eu remo o barco-farol. Seis gaivotas de brasa sentaram na minha lâmpada e bicam o vidro, e sem a luz os barcos batem na obsidiana. A vó Edna de vocês uma vez remou comigo até o recife e cantou o caminho inteiro para eu não ter medo. Espantem as gaivotas, e eu dou um barco que não queima."),
            new LocalizationEntry("quest.city_hinokura_ember_gulls_on_the_lighthouse.active",
                "They circle the lamp when it is lit and dive at whoever comes up the stone pier.",
                "Elas rodeiam a lâmpada quando ela acende e mergulham em quem sobe o cais de pedra."),

            // ================= Cais de Mesektet — Sinuhe, o Barqueiro-Chefe =================
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.title", "Crocodiles on the Quay", "Crocodilos no Cais"),
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.description",
                "Crocodiles dimmed by the shadow climb out of the dark river every night and lie across the landing of the Cais da Barca, where the Mesektet moors before the next hour. The rowers cannot reach the oars, and a barque that leaves late opens the next pier late. Sinuhe, the chief boatman, who once went far away and came home old, asked the cousins to chase the crocodiles back into the water.",
                "Crocodilos apagados pela sombra sobem do rio escuro toda noite e deitam atravessados no cais da barca, onde a Mesektet atraca antes da hora seguinte. Os remadores não alcançam os remos, e barca que sai atrasada abre o píer seguinte atrasado. O Sinuhe, o barqueiro-chefe, que um dia foi para muito longe e voltou para casa velho, pediu aos primos que espantem os crocodilos de volta para a água."),
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.obj_chase_the_crocodiles", "Chase the crocodiles of the dark river off the landing", "Espantar os crocodilos do rio escuro do cais da barca"),
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.journal",
                "With the crocodiles gone, the Mesektet left on the hour and Sinuhe let Joaquim push the barque off the landing with the long pole. It went straight on the first try. Sinuhe said he had waited forty years to see a boy push straight on the first try, and that it was worth the trip home.",
                "Com os crocodilos embora, a Mesektet saiu na hora certa e o Sinuhe deixou o Joaquim empurrar a barca do cais com a vara comprida. Foi reto na primeira. O Sinuhe disse que esperou quarenta anos para ver um menino empurrar reto na primeira, e que valeu a viagem de volta para casa."),
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.offer",
                "Edna's grandchildren, on the river of the night! I went very far once, children, and the only thing I wanted was to come home. Your grandpa Jorge understood that; he sat on this quay and told me about his rice until the barque came. Eight crocodiles of the shadow lie on my landing every night. Chase them back into the water, so the barque leaves on the hour.",
                "Os netos da Edna, no rio da noite! Eu fui muito longe uma vez, crianças, e a única coisa que eu queria era voltar para casa. O vô Jorge de vocês entendeu isso; sentou neste cais e me contou do arroz dele até a barca chegar. Oito crocodilos da sombra deitam no meu cais toda noite. Espantem eles de volta para a água, para a barca sair na hora."),
            new LocalizationEntry("quest.city_mesektet_crocodiles_on_the_quay.active",
                "They come up the bank where the papyrus is thickest, when the lamps of the piers are low.",
                "Eles sobem pela margem onde o papiro é mais fechado, quando as lamparinas dos píeres estão baixas."),

            // ================= Cais de Mesektet — Djedi, o Mágico =================
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.title", "Scorpions in the Sands", "Escorpiões no Areal"),
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.description",
                "Black scorpions, dimmed by the shadow, have crept down from the Hidden Sands into the sandbank behind the quay, where Djedi draws his circles of light for the pupils of magic. They sting the feet of whoever sits to learn, and a pupil who jumps forgets the spell. Djedi, the magician who is a hundred and ten years old, asked the cousins to chase the scorpions back into the dark, and promised them a lamp that does not go out.",
                "Escorpiões negros, apagados pela sombra, desceram do Areal Escondido para o banco de areia atrás do cais, onde o Djedi desenha os círculos de luz para os alunos de magia. Eles picam o pé de quem senta para aprender, e aluno que pula esquece o feitiço. O Djedi, o mágico de cento e dez anos, pediu aos primos que espantem os escorpiões de volta para o escuro, e prometeu uma lamparina que não apaga."),
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.obj_chase_the_scorpions", "Chase the black scorpions out of the sands", "Espantar os escorpiões negros do areal"),
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.journal",
                "With the scorpions gone, Djedi drew a circle of light on the sand and let Lavine light it. It burned blue instead of gold. Djedi laughed for a long time, gave the cousins a runic lamp for the hours of the river and said that blue is also light, and that in a hundred and ten years he had never seen it.",
                "Com os escorpiões embora, o Djedi desenhou um círculo de luz na areia e deixou a Lavine acender. Acendeu azul em vez de dourado. O Djedi riu um tempão, deu aos primos uma lamparina rúnica para as horas do rio e disse que azul também é luz, e que em cento e dez anos ele nunca tinha visto."),
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.offer",
                "You chased Sinuhe's crocodiles! Good, good. I am Djedi; I teach magic on the sand, slowly, because I am a hundred and ten years old and I have time. Six black scorpions sting my pupils. Your grandma Edna came to my circle once and learned to light a lamp in one try; I still tell that story. Chase them, and I will give you a lamp for the night that never ends.",
                "Vocês espantaram os crocodilos do Sinuhe! Bom, bom. Eu sou o Djedi; eu ensino magia na areia, devagar, porque tenho cento e dez anos e tenho tempo. Seis escorpiões negros picam os meus alunos. A vó Edna de vocês veio no meu círculo uma vez e aprendeu a acender a lamparina de primeira; eu ainda conto essa história. Espantem eles, e eu dou uma lamparina para a noite que não acaba."),
            new LocalizationEntry("quest.city_mesektet_scorpions_in_the_sands.active",
                "They hide under the sand where the circles of light have gone dark.",
                "Eles se escondem debaixo da areia onde os círculos de luz apagaram."),

            // ================= Dur-Jarras — Utnapishtim =================
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.title", "Lions on the Canals", "Leões nos Canais"),
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.description",
                "The brick lions of the old glazed walls, dimmed by the shadow, come down at night and lie across the canals of Dur-Jarras, right where the rafts must pass. Utnapishtim, who keeps the Relógio de Zurvan and once saw a whole world under water, asked the cousins to chase the lions back to the walls.",
                "Os leões de tijolo dos muros vidrados antigos, apagados pela sombra, descem de noite e deitam atravessados nos canais de Dur-Jarras, bem onde as balsas passam. O Utnapishtim, que cuida do Relógio de Zurvan e um dia viu o mundo inteiro debaixo d'água, pediu aos primos que espantem os leões de volta para os muros."),
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.obj_chase_the_lions", "Chase the dimmed brick lions off the canals", "Espantar os leões de tijolo dos canais"),
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.journal",
                "With the lions gone, the rafts passed on the hour. Utnapishtim let Maria read the shadow on the clock and wrote the hour down exactly as she said it. He said that in all the years since the water he had never once been told the time by someone so sure.",
                "Com os leões embora, as balsas passaram na hora certa. O Utnapishtim deixou a Maria ler a sombra do relógio e anotou a hora do jeitinho que ela falou. Ele disse que, em todos os anos depois da água, nunca ninguém tinha dito a hora para ele com tanta certeza."),
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.offer",
                "Edna's grandchildren, here at the edge of everything! I saw the water rise once, children; since then I watch the clock and the canals. Your grandpa Jorge came through here and asked me if the flood was worse than his rainy season. It was. Eight brick lions lie across my canals and the rafts cannot pass. Chase them back to the walls.",
                "Os netos da Edna, aqui na beira de tudo! Eu vi a água subir uma vez, crianças; desde então eu olho o relógio e os canais. O vô Jorge de vocês passou aqui e me perguntou se o dilúvio foi pior que a chuva da roça dele. Foi. Oito leões de tijolo deitaram nos meus canais e as balsas não passam. Espantem eles de volta para os muros."),
            new LocalizationEntry("quest.city_dur_jarras_lions_on_the_canals.active",
                "They lie across the water where the bricks of the canal are warmest, after the ziggurat lights up.",
                "Eles deitam na água onde o tijolo do canal é mais quente, depois que o zigurate acende."),

            // ================= Dur-Jarras — Sin-leqi-unninni =================
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.title", "Beetles on the Tablets", "Besouros nas Tábuas"),
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.description",
                "Beetles dimmed by the shadow have climbed the reed shelves of the house of tablets and chew through them, and a shelf that falls breaks a hundred tablets at once. Sin-leqi-unninni, the librarian who copied the oldest tale of all, asked the cousins to chase the beetles out before the next flood comes for the rest.",
                "Besouros apagados pela sombra subiram as prateleiras de junco da casa das tábuas e estão roendo tudo, e prateleira que cai quebra cem tábuas de uma vez. O Sin-leqi-unninni, o bibliotecário que copiou o conto mais antigo de todos, pediu aos primos que espantem os besouros antes que a próxima cheia leve o resto."),
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.obj_chase_the_beetles", "Chase the beetles from the shelves of tablets", "Espantar os besouros das prateleiras de tábuas"),
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.journal",
                "With the beetles gone, the shelves stood straight again. Sin-leqi-unninni gave the cousins the reed boat he keeps for the flood, and Ícaro pressed his thumb into wet clay to sign for it. The librarian filed the thumb among the signatures of kings.",
                "Com os besouros embora, as prateleiras ficaram retas de novo. O Sin-leqi-unninni deu aos primos o barco de junco que guardava para a cheia, e o Ícaro apertou o dedão no barro molhado para assinar. O bibliotecário arquivou o dedão junto das assinaturas dos reis."),
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.offer",
                "You chased Utnapishtim's lions! Good. I am Sin-leqi-unninni; I copy tablets, and six beetles are chewing the shelves that hold them. Your grandma Edna once dictated a recipe here and made me fix three signs. Chase the beetles, and I will give you the reed boat I keep for the flood.",
                "Vocês espantaram os leões do Utnapishtim! Bom. Eu sou o Sin-leqi-unninni; eu copio tábuas, e seis besouros estão roendo as prateleiras que seguram elas. A vó Edna de vocês ditou uma receita aqui uma vez e me fez corrigir três sinais. Espantem os besouros, e eu dou o barco de junco que guardo para a cheia."),
            new LocalizationEntry("quest.city_dur_jarras_beetles_on_the_tablets.active",
                "They climb the reed shelves when the lamps of the house of tablets are low.",
                "Eles sobem as prateleiras de junco quando as lamparinas da casa das tábuas estão baixas."),

            // ================= Fortaleza da Última Lâmpada — Pamour =================
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.title", "Bats on the Rampart", "Morcegos na Muralha"),
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.description",
                "Swarms of bats dimmed by the dark come up out of the abyss and beat their wings against the niches of the rampart until the little flames go out, and every lamp that goes out lets the shadow climb a little higher. Pamour, who commands the lamps of the Fortaleza, asked the cousins to chase the bats back down.",
                "Enxames de morcegos apagados pela treva sobem do abismo e batem as asas nos nichos da muralha até as chamas pequenas apagarem, e cada lâmpada que apaga deixa a sombra subir mais um pouco. O Pamour, que comanda as lâmpadas da Fortaleza, pediu aos primos que espantem os morcegos de volta para baixo."),
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.obj_chase_the_bats", "Chase the bats of the Dark off the rampart", "Espantar os morcegos da Treva da muralha"),
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.journal",
                "With the bats gone, the niches of the rampart stayed lit all the way to the fifth gate. Pamour let Joaquim light the last one with his own hand and stood at attention while he did it. He said a commander can count the lamps, but it takes a boy to be glad about them.",
                "Com os morcegos embora, os nichos da muralha ficaram acesos até o quinto portão. O Pamour deixou o Joaquim acender o último com a própria mão e ficou em posição de sentido enquanto ele acendia. Ele disse que comandante conta as lâmpadas, mas é menino que fica feliz com elas."),
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.offer",
                "Edna's grandchildren, down here at the last lamp! Good. I am Pamour; I command a thousand little flames and the shadow is counting them with me. Your grandpa Jorge once came to the rampart and asked why nobody had put a roof on the abyss. Eight swarms of bats are putting out my niches. Chase them back down.",
                "Os netos da Edna, aqui embaixo na última lâmpada! Bom. Eu sou o Pamour; eu comando mil chamas pequenas e a sombra conta elas comigo. O vô Jorge de vocês veio na muralha uma vez e perguntou por que ninguém botava telhado no abismo. Oito enxames de morcegos estão apagando os meus nichos. Espantem eles de volta para baixo."),
            new LocalizationEntry("quest.city_ultima_lampada_bats_on_the_rampart.active",
                "They come up the wall when the dark tide rises, and they hate the amber light.",
                "Eles sobem a muralha quando a maré de treva sobe, e têm raiva da luz âmbar."),

            // ================= Fortaleza da Última Lâmpada — Makarios =================
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.title", "Ushabti on the Letter Road", "Ushabtis na Estrada das Cartas"),
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.description",
                "Old rope-bound ushabti, dimmed by the shadow, have wandered onto the road the letter carriers use to come down from the Grutas do Limiar, and no letter has arrived in weeks. Makarios, who writes to his sons far away every week without fail, asked the cousins to chase them off.",
                "Ushabtis antigos amarrados de corda, apagados pela sombra, se perderam na estrada por onde os carregadores de cartas descem das Grutas do Limiar, e faz semanas que não chega carta nenhuma. O Makarios, que escreve para os filhos longe toda semana sem falta, pediu aos primos que espantem eles dali."),
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.obj_chase_the_ushabti", "Chase the dimmed ushabti off the letter road", "Espantar os ushabtis apagados da estrada das cartas"),
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.journal",
                "With the road clear, a bag of letters came down at last. Makarios gave the cousins the runic lamp he keeps for reading in the dark and read one letter aloud, slowly, twice. Then Maria asked him to write back that the cousins had been there, and he did.",
                "Com a estrada livre, um saco de cartas chegou enfim. O Makarios deu aos primos a lamparina rúnica que guardava para ler no escuro e leu uma carta em voz alta, devagar, duas vezes. Depois a Maria pediu para ele escrever de volta que os primos tinham passado ali, e ele escreveu."),
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.offer",
                "You chased Pamour's bats. Good. I am Makarios; I write to my sons, and six ushabti have sat down on the road and my letters do not get through. Your grandpa Jorge writes letters the same way I do: too long, and always about the weather. Chase them off the road, and I will give you my runic lamp.",
                "Vocês espantaram os morcegos do Pamour. Bom. Eu sou o Makarios; eu escrevo para os meus filhos, e seis ushabtis sentaram na estrada e as minhas cartas não passam. O Vô Jorge de vocês escreve carta igual a mim: comprida demais e sempre falando do tempo. Espantem eles da estrada, e eu dou a minha lamparina rúnica."),
            new LocalizationEntry("quest.city_ultima_lampada_ushabti_on_the_letter_road.active",
                "They stand in the road with nothing to carry, and they will not move for a letter.",
                "Eles ficam parados na estrada sem nada para carregar, e não saem da frente por causa de carta."),

            // ================= Cais da Coluna — Ammo =================
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.title", "Stowaways in the Bales", "Clandestinas nos Fardos"),
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.description",
                "Ammo's last caravan came all the way up to the Cais da Coluna with a present from every city of the island, and shadows rode up with it, hidden between the bales. They want to reach the sky without paying the way. Ammo asked the cousins to chase them out before the Barca da Lua takes the bales aboard.",
                "A última caravana do Ammo subiu até o Cais da Coluna com um presente de cada cidade da ilha, e sombras vieram junto, escondidas entre os fardos. Elas querem chegar no céu sem pagar o caminho. O Ammo pediu aos primos que espantem elas antes de a Barca da Lua levar os fardos."),
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.obj_chase_the_stowaways", "Chase the stowaway shadows out of the bales", "Espantar as sombras clandestinas dos fardos"),
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.journal",
                "With the shadows gone, Ammo untied the last bale himself, and there was nothing in it but a jar of Grandma Edna's Golden Brick and a note in her hand. He sat down on the bale and laughed until he cried. He said he had carried that jar for three years without knowing, and that it was exactly like her.",
                "Com as sombras embora, o Ammo desamarrou o último fardo ele mesmo, e dentro só tinha um pote de Torrão Dourado da Vó Edna e um bilhete com a letra dela. Ele sentou no fardo e riu até chorar. Disse que carregou aquele pote três anos sem saber, e que isso era a cara dela."),
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.offer",
                "Jorge's grandchildren, up here where the road ends! Sit, sit. I am Ammo, and this is the last caravan I will ever lead, and eight shadows have stowed away in my bales. Your grandpa would say to charge them a fare. Chase them off instead.",
                "Os netos do Jorge, aqui em cima onde a estrada acaba! Senta, senta. Eu sou o Ammo, e essa é a última caravana que eu vou puxar, e oito sombras se esconderam nos meus fardos. O vô de vocês diria para cobrar passagem. Espantem elas, que é melhor."),
            new LocalizationEntry("quest.city_cais_coluna_stowaways_in_the_bales.active",
                "They slide between the bales when nobody is looking, and they are very quiet about it.",
                "Elas escorregam entre os fardos quando ninguém está olhando, e são bem quietas nisso."),

            // ================= Cais da Coluna — Adda =================
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.title", "Birds on the Jars", "Aves nas Jarras"),
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.description",
                "Birds dimmed by the last of the shadow have come to roost on the twelve jars of the Roda Celeste, and every jar they sit on carries less light up the Coluna. Adda, who kept the Tower for years and now looks after the Wheel, asked the cousins to shoo them away.",
                "Aves apagadas pelo resto da sombra vieram pousar nas doze jarras da Roda Celeste, e cada jarra em que elas sentam leva menos luz para a Coluna. O Adda, que guardou a Torre por anos e agora cuida da Roda, pediu aos primos que enxotem elas."),
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.obj_chase_the_birds", "Shoo the dimmed birds off the jars of the Wheel", "Enxotar as aves apagadas das jarras da Roda"),
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.journal",
                "When the jars were clear, the Wheel gave one long turn and a thread of light climbed the Coluna higher than Adda had seen in years. He cried, of course. Then he gave Maithe the storm cloak he wore on the Tower and told her the wind up here was not to be trusted either.",
                "Quando as jarras ficaram livres, a Roda deu uma volta longa e um fio de luz subiu pela Coluna mais alto do que o Adda via fazia anos. Ele chorou, claro. Depois deu à Maithe a capa de tempestade que usava na Torre e disse que o vento aqui em cima também não é de confiança."),
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.offer",
                "You chased Ammo's stowaways. Good. I am Adda; I kept the Tower until my knees retired me, and now I keep the Wheel, which is the same work with a better view. Six dimmed birds are sitting on my jars. Shoo them off and you can have my old storm cloak.",
                "Vocês espantaram as clandestinas do Ammo. Bom. Eu sou o Adda; guardei a Torre até os meus joelhos me aposentarem, e agora guardo a Roda, que é o mesmo trabalho com uma vista melhor. Seis aves apagadas estão sentadas nas minhas jarras. Enxotem elas e a minha capa de tempestade velha é de vocês."),
            new LocalizationEntry("quest.city_cais_coluna_birds_on_the_jars.active",
                "They come back to the same jar every time. Birds are like that. So am I.",
                "Elas voltam sempre para a mesma jarra. Ave é assim. Eu também sou."),

            // ================================================================================================================
            // On the road (CityQuestCatalog, regions 9–16): the givers send the cousins out to a zone of the region at a level.
            // ================================================================================================================
            // ================= Besouros no Cerne (nível 124, arvoredo_de_haripushpa) =================
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.title", "Beetles in the Heartwood", "Besouros no Cerne"),
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.description",
                "Bark beetles dimmed by the shadow are boring into the heart of the sleeping trunks, where the trees keep the light they drank. Aryaman Puhr asked the cousins to clear them before a trunk wakes up hollow.",
                "Besouros-casca apagados pela sombra estão furando o cerne dos troncos adormecidos, onde as árvores guardam a luz que beberam. O Aryaman Puhr pediu aos primos que tirem os besouros antes que um tronco acorde oco."),
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.obj_clear_the_heartwood", "Clear the bark beetles out of the sleeping trunks", "Tirar os besouros-casca dos troncos adormecidos"),
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.journal",
                "Lavine put her ear to a trunk and said it was breathing slower, the way Grandma Edna breathes when she naps after lunch. Aryaman laughed and said that is exactly how a tree should sound.",
                "A Lavine encostou o ouvido num tronco e disse que ele respirava mais devagar, do jeito que a Vó Edna respira quando cochila depois do almoço. O Aryaman riu e disse que é assim mesmo que árvore tem de soar."),
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.offer",
                "The smoke birds are gone, but now the beetles go deeper, into the heartwood. Seven of them, cousins. The trees will not thank you, they are asleep, but I will.",
                "Os pássaros de fumaça foram embora, mas agora os besouros vão mais fundo, no cerne. Sete deles, primos. As árvores não vão agradecer, estão dormindo, mas eu agradeço."),
            new LocalizationEntry("quest.city_arvoredo_beetles_in_the_heartwood.active",
                "Listen for the ticking inside the bark. A beetle at work ticks like Ícaro's pocket watch.",
                "Escutem o tique-taque dentro da casca. Besouro trabalhando faz barulho de relógio de bolso do Ícaro."),

            // ================= Ochokochis na Torre de Vigia (nível 128, torre_de_vigia) =================
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.title", "Ochokochi at the Watchtower", "Ochokochis na Torre de Vigia"),
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.description",
                "The ochokochi of the Svan forests, dimmed by the shadow, have climbed into the old watchtower on the way to Amirani's chain and swing their axe-chests at whoever passes. Virogdad dreamed of it twice and asked the cousins to chase them off.",
                "Os ochokochis das florestas svan, apagados pela sombra, subiram na velha torre de vigia do caminho da corrente de Amirani e batem o peito de machado em quem passa. O Virogdad sonhou com isso duas vezes e pediu aos primos que espantem eles."),
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.obj_chase_the_ochokochi", "Chase the ochokochi out of the watchtower", "Espantar os ochokochis da torre de vigia"),
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.journal",
                "From the top of the tower you can see the chain of Amirani shining in the snow. Joaquim tried to lift one of its links and said it was lighter than Grandpa Jorge's toolbox. Nobody believed him.",
                "Do alto da torre dá para ver a corrente de Amirani brilhando na neve. O Joaquim tentou levantar um elo e disse que era mais leve que a caixa de ferramentas do Vô Jorge. Ninguém acreditou."),
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.offer",
                "I dreamed it again: a tower, six hairy shadows and five children climbing. You are the five. Go before the dream changes its mind.",
                "Sonhei de novo: uma torre, seis sombras peludas e cinco crianças subindo. Vocês são as cinco. Vão antes que o sonho mude de ideia."),
            new LocalizationEntry("quest.city_fortim_ochokochi_at_the_watchtower.active",
                "In my dream they fled when somebody laughed. I do not know if that helps.",
                "No meu sonho eles fugiam quando alguém ria. Não sei se ajuda."),

            // ================= Águias sobre o Abrigo (nível 164, gruta_abrigo) =================
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.title", "Eagles over the Shelter", "Águias sobre o Abrigo"),
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.description",
                "Storm eagles circle the shelter cave of the Ays gorge and tear the paper charms Tadi folds for the travellers who sleep there. Tadi asked the cousins to chase them so the charms can hold the Living Wind in.",
                "Águias de tempestade rondam a gruta-abrigo da garganta dos Ays e rasgam os amuletos de papel que a Tadi dobra para quem dorme lá. A Tadi pediu aos primos que espantem as águias para os amuletos segurarem o Vento Vivo do lado de dentro."),
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.obj_chase_the_storm_eagles", "Chase the storm eagles away from the shelter cave", "Espantar as águias de tempestade da gruta-abrigo"),
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.journal",
                "Tadi taught Maithe to fold a paper crane that turns its head into the wind. Ícaro opened one to see how it worked and could not fold it back. Tadi folded him a second one, with a frown drawn on it.",
                "A Tadi ensinou a Maithe a dobrar um grou de papel que vira a cabeça para o vento. O Ícaro desdobrou um para ver como funcionava e não conseguiu dobrar de volta. A Tadi dobrou outro para ele, com uma cara emburrada desenhada."),
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.offer",
                "My charms in the gorge are torn to confetti again. Seven eagles, cousins. Your grandma Edna slept in that cave once, did you know? She left me a recipe on the wall.",
                "Os meus amuletos da garganta viraram confete de novo. Sete águias, primos. A Vó Edna de vocês já dormiu naquela gruta, sabiam? Deixou uma receita escrita na parede para mim."),
            new LocalizationEntry("quest.city_farnkesh_eagles_over_the_shelter.active",
                "The eagles come with the gusts. Wait for the wind to drop and they drop with it.",
                "As águias vêm com as rajadas. Esperem o vento baixar que elas baixam junto."),

            // ================= Pedras na Garganta (nível 168, garganta_dos_ays) =================
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.title", "Stones in the Gorge", "Pedras na Garganta"),
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.description",
                "Rolling stones woken by the destroying wind bounce down the gorge of the Ays and crack the bell posts that mark the safe path. Shad-Ohrmizd asked the cousins to stop them before the last post falls.",
                "Pedras-rolantes acordadas pelo vento destruidor descem pulando a garganta dos Ays e racham os postes de sino que marcam o caminho seguro. O Shad-Ohrmizd pediu aos primos que parem as pedras antes que o último poste caia."),
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.obj_clear_the_gorge", "Stop the rolling stones of the gorge", "Parar as pedras-rolantes da garganta"),
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.journal",
                "With the stones quiet, the little bells of the gorge rang all the way down to Farnkesh. Maria counted forty-one. Shad-Ohrmizd says there are forty-two, and that the last one only rings for Grandpa Jorge.",
                "Com as pedras quietas, os sininhos da garganta tocaram até lá embaixo em Farnkesh. A Maria contou quarenta e um. O Shad-Ohrmizd diz que são quarenta e dois, e que o último só toca para o Vô Jorge."),
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.offer",
                "The posts of the gorge are cracking, and a path without bells is a path for the ill wind. Seven stones, cousins. Push back.",
                "Os postes da garganta estão rachando, e caminho sem sino é caminho do vento ruim. Sete pedras, primos. Empurrem de volta."),
            new LocalizationEntry("quest.city_farnkesh_stones_in_the_gorge.active",
                "A stone that rolls has no ears. Step aside first, strike after.",
                "Pedra que rola não tem ouvido. Primeiro saiam da frente, depois batam."),

            // ================= Irbis no Fiorde das Presas (nível 202, fiorde_das_presas) =================
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.title",
                "Irbis in the Fjord of Tusks",
                "Irbis no Fiorde das Presas"),
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.description",
                "Snow leopards dimmed by the shadow stalk the Fjord of Tusks, where the mammoths of the galleries come down to drink, and scatter the herd Yirkap follows on his skis. He asked the cousins to chase them off.",
                "Leopardos-das-neves apagados pela sombra rondam o Fiorde das Presas, onde os mamutes das galerias descem para beber, e espalham a manada que o Yirkap segue de esqui. Ele pediu aos primos que espantem os irbis."),
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.obj_chase_the_irbis",
                "Chase the irbis out of the Fjord of Tusks",
                "Espantar os irbis do Fiorde das Presas"),
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.journal",
                "Yirkap lent Maria his old skis and she fell eleven times and wrote every fall down. On the twelfth try she slid all the way to the herd. Yirkap says Grandpa Jorge never got past the fourth.",
                "O Yirkap emprestou os esquis velhos para a Maria e ela caiu onze vezes e anotou cada tombo. Na décima segunda ela deslizou até a manada. O Yirkap diz que o Vô Jorge nunca passou da quarta."),
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.offer",
                "The gulls are gone from my racks, good. Now the irbis hunt the mammoths at the Fjord of Tusks. Six of them, and grey as smoke. Bring Joaquim, the mammoths like big people.",
                "As gaivotas saíram dos meus varais, bom. Agora os irbis caçam os mamutes no Fiorde das Presas. Seis deles, cinzentos de fumaça. Levem o Joaquim, que mamute gosta de gente grande."),
            new LocalizationEntry("quest.city_porto_irbis_in_the_fjord_of_tusks.active",
                "An irbis hides on the rock above, never below. Look up.",
                "Irbis se esconde na pedra de cima, nunca embaixo. Olhem para o alto."),

            // ================= Focas sob as Auroras (nível 208, mar_das_auroras) =================
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.title",
                "Seals under the Auroras",
                "Focas sob as Auroras"),
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.description",
                "Leopard seals dimmed by the shadow have come out on the floes of the Sea of Auroras and break the ice path the people of the Lua Branca walk to see the lights. Yirkap asked the cousins to chase them back into the water.",
                "Focas-leopardo apagadas pela sombra subiram nas banquisas do Mar das Auroras e quebram o caminho de gelo por onde o povo da Lua Branca anda para ver as luzes. O Yirkap pediu aos primos que espantem elas de volta para a água."),
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.obj_chase_the_leopard_seals",
                "Chase the leopard seals off the floes",
                "Espantar as focas-leopardo das banquisas"),
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.journal",
                "With the path clear we lay on the ice and watched the auroras. Lavine says they are light going home. Yirkap says Grandma Edna told him the same thing, on this same floe, a long time ago.",
                "Com o caminho livre a gente deitou no gelo e ficou olhando as auroras. A Lavine diz que são luz voltando para casa. O Yirkap diz que a Vó Edna disse a mesma coisa para ele, nessa mesma banquisa, muito tempo atrás."),
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.offer",
                "Under the auroras the floes are full of grey seals biting the path. Seven of them. Go, and look up when you are done: that is the reward.",
                "Debaixo das auroras as banquisas estão cheias de focas cinzentas mordendo o caminho. Sete delas. Vão, e olhem para cima quando acabarem: a recompensa é essa."),
            new LocalizationEntry("quest.city_porto_seals_under_the_auroras.active",
                "A seal on the ice is slow. A seal in the water is not. Keep them on the ice.",
                "Foca no gelo é lenta. Foca na água não é. Segurem elas no gelo."),

            // ================= Focas debaixo do Kul (nível 232, fiorde_do_kul) =================
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.title", "Seals under the Kul", "Focas debaixo do Kul"),
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.description",
                "Shadow seals have come up the black fjord of old Kul and break the fishing holes the people of the Lua Branca cut in the ice. Pera, the good giant, cannot bend down that far, so he asked the cousins.",
                "Focas de sombra subiram pelo fiorde negro do velho Kul e quebram os buracos de pesca que o povo da Lua Branca abre no gelo. O Pera, o gigante bom, não consegue se abaixar tanto, então pediu aos primos."),
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.obj_chase_the_shadow_seals", "Chase the shadow seals off the fjord of the Kul", "Espantar as focas de sombra do fiorde do Kul"),
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.journal",
                "Pera carried all five of us back on his shoulders, two on each side and Lavine on his head. She says the view from up there is the same as from the Barca, only warmer.",
                "O Pera carregou nós cinco de volta nos ombros, dois de cada lado e a Lavine na cabeça. Ela diz que a vista lá de cima é igual à da Barca, só que mais quentinha."),
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.offer",
                "Little ones! The seals of the Kul are grey as soot and they bite the ice. Seven of them. I would go, but the ice does not like my feet.",
                "Pequenos! As focas do Kul estão cinzentas de fuligem e mordem o gelo. Sete delas. Eu iria, mas o gelo não gosta dos meus pés."),
            new LocalizationEntry("quest.city_porto_seals_under_the_kul.active",
                "If the ice sings under you, walk lighter. Not like me.",
                "Se o gelo cantar debaixo de vocês, pisem mais leve. Não igual a mim."),

            // ================= Bombas no Echeyde (nível 236, monte_echeyde) =================
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.title", "Bombs on Echeyde", "Bombas no Echeyde"),
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.description",
                "The consuming fire under Mount Echeyde spits living volcanic bombs that roll down onto the lacquer trees of the slopes. Mestra Akane needs that sap and asked the cousins to calm the bombs.",
                "O fogo devorador debaixo do Monte Echeyde cospe bombas vulcânicas vivas que rolam para cima das árvores de laca da encosta. A Mestra Akane precisa dessa seiva e pediu aos primos que acalmem as bombas."),
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.obj_calm_the_bombs", "Calm the volcanic bombs of Echeyde", "Acalmar as bombas vulcânicas do Echeyde"),
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.journal",
                "Akane let Ícaro paint one stroke of lacquer on a bowl. It took him an hour. She says that is fast, and that the Living Fire likes patient hands, like Grandma Edna's on the tacho.",
                "A Akane deixou o Ícaro passar uma pincelada de laca numa tigela. Levou uma hora. Ela diz que foi rápido, e que o Fogo Vivo gosta de mão paciente, igual à da Vó Edna no tacho."),
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.offer",
                "The mountain is coughing up angry stones again, and my lacquer trees are on its slope. Six bombs, cousins. Calm them, do not kick them.",
                "A montanha está tossindo pedra brava de novo, e as minhas árvores de laca ficam na encosta. Seis bombas, primos. Acalmem, não chutem."),
            new LocalizationEntry("quest.city_hinokura_bombs_on_echeyde.active",
                "A bomb that glows white is about to burst. Wait for red.",
                "Bomba que brilha branco está para estourar. Esperem ficar vermelha."),

            // ================= Coral no Recife (nível 244, recife_de_obsidiana) =================
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.title", "Coral on the Reef", "Coral no Recife"),
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.description",
                "Ember coral grows over the obsidian reef and burns the hulls of the reed boats. Sango the boatwoman asked the cousins to break the live coral before it closes the passage of the Barco-Farol.",
                "Coral de brasa cresce sobre o recife de obsidiana e queima o casco dos barcos de junco. A Sango, a barqueira, pediu aos primos que quebrem o coral vivo antes que ele feche a passagem do Barco-Farol."),
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.obj_break_the_ember_coral", "Break the ember coral of the obsidian reef", "Quebrar o coral de brasa do recife de obsidiana"),
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.journal",
                "Sango rowed us round the reef at night to show the glass shining. Maria wrote down the way, rock by rock, for when we come back. Sango said only Grandpa Jorge ever did that before.",
                "A Sango remou com a gente em volta do recife de noite para mostrar o vidro brilhando. A Maria anotou o caminho, pedra por pedra, para quando a gente voltar. A Sango disse que só o Vô Jorge tinha feito isso antes."),
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.offer",
                "My gulls are gone, thank you. Now the reef itself is burning: ember coral, seven clumps of it. Break them and the Barco-Farol can pass.",
                "As minhas gaivotas foram embora, obrigada. Agora é o próprio recife que queima: coral de brasa, sete touceiras. Quebrem e o Barco-Farol passa."),
            new LocalizationEntry("quest.city_hinokura_coral_on_the_reef.active",
                "Do not touch the coral with bare hands. Ask Joaquim, he knows now.",
                "Não encostem a mão no coral. Perguntem para o Joaquim, agora ele sabe."),

            // ================= Peixes-Lâmina nos Canais Quentes (nível 248, canais_quentes) =================
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.title", "Blade Fish in the Warm Channels", "Peixes-Lâmina nos Canais Quentes"),
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.description",
                "Blade fish dimmed by the shadow cut the lines where Akane soaks her lacquered boards in the warm channels of the reef. She asked the cousins to chase them before the boards drift away.",
                "Peixes-lâmina apagados pela sombra cortam as cordas onde a Akane deixa as tábuas laqueadas de molho nos canais quentes do recife. Ela pediu aos primos que espantem os peixes antes que as tábuas saiam boiando."),
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.obj_chase_the_blade_fish", "Chase the blade fish out of the warm channels", "Espantar os peixes-lâmina dos canais quentes"),
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.journal",
                "Akane gave each of us a lacquered chopstick with our name in gold. Lavine wants to send hers to Grandma Edna. Joaquim already broke his on a rice cake.",
                "A Akane deu para cada um de nós um hashi laqueado com o nosso nome em dourado. A Lavine quer mandar o dela para a Vó Edna. O Joaquim já quebrou o dele num bolinho de arroz."),
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.offer",
                "My boards soak in the warm channels for a hundred days, and the blade fish cut them loose on the ninety-ninth. Six of them, please. Quickly.",
                "As minhas tábuas ficam de molho nos canais quentes cem dias, e os peixes-lâmina soltam elas no nonagésimo nono. Seis deles, por favor. Depressa."),
            new LocalizationEntry("quest.city_hinokura_blade_fish_in_the_warm_channels.active",
                "They shine before they strike. Watch the water, not the sky.",
                "Eles brilham antes de atacar. Olhem a água, não o céu."),

            // ================= A Serpente do Areal Escondido (nível 274, areal_escondido) =================
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.title", "The Serpent in the Hidden Sands", "A Serpente do Areal Escondido"),
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.description",
                "Three-headed serpents coil in the Areal Escondido, where the night barque passes the doors that close. Djedi the magician says each head guards one hour, and asked the cousins to chase them so the hours can pass.",
                "Serpentes de três cabeças se enrolam no Areal Escondido, onde a barca da noite passa pelas portas que se fecham. O Djedi, o mágico, diz que cada cabeça guarda uma hora, e pediu aos primos que espantem elas para as horas passarem."),
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.obj_chase_the_serpents", "Chase the three-headed serpents of the hidden sands", "Espantar as serpentes de três cabeças do areal escondido"),
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.journal",
                "Djedi put a head back on a clay goose to show us his trick. Ícaro wants to know how. Djedi says magic is a trick that nobody has explained yet, and that Grandpa Jorge almost did once.",
                "O Djedi colou de volta a cabeça de um ganso de barro para mostrar o truque. O Ícaro quer saber como. O Djedi diz que mágica é truque que ninguém explicou ainda, e que o Vô Jorge quase explicou uma vez."),
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.offer",
                "The scorpions were the small trouble. In the hidden sands there is a big one, with three heads, and many of it. Six. Bring me back all your heads, please.",
                "Os escorpiões eram o problema pequeno. No areal escondido tem um grande, de três cabeças, e muitos dele. Seis. Me tragam de volta todas as cabeças de vocês, por favor."),
            new LocalizationEntry("quest.city_mesektet_serpent_in_the_hidden_sands.active",
                "Strike the middle head. The other two always argue about what to do.",
                "Batam na cabeça do meio. As outras duas sempre discutem o que fazer."),

            // ================= Mordedores no Anel Externo (nível 280, anel_externo) =================
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.title", "Biters on the Outer Ring", "Mordedores no Anel Externo"),
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.description",
                "Shadow biters swarm the outer ring of Mehen, the coiled serpent the barque must cross every night. Sinuhe the chief boatman asked the cousins to clear the ring before the rowers lose their way in the coils.",
                "Mordedores de sombra infestam o anel externo de Mehen, a serpente enrolada que a barca precisa atravessar toda noite. O Sinuhe, o barqueiro-chefe, pediu aos primos que limpem o anel antes que os remadores se percam nas voltas."),
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.obj_chase_the_biters", "Chase the shadow biters off the outer ring", "Espantar os mordedores de sombra do anel externo"),
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.journal",
                "Sinuhe drew Mehen in the sand: a game board, a serpent, a road. Maria won the first game. Sinuhe says only one other person ever beat him at it, an old man who made rapadura.",
                "O Sinuhe desenhou Mehen na areia: tabuleiro, serpente e estrada. A Maria ganhou a primeira partida. O Sinuhe diz que só uma outra pessoa já ganhou dele, um velho que fazia rapadura."),
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.offer",
                "The rings of Mehen are a road for the barque, and something small and hungry is on the outer one. Eight of them. Row hard.",
                "Os anéis de Mehen são estrada para a barca, e tem coisa pequena e esfomeada no de fora. Oito delas. Remem forte."),
            new LocalizationEntry("quest.city_mesektet_biters_on_the_outer_ring.active",
                "They bite and run back into the dark. Keep together, like rowers.",
                "Elas mordem e voltam correndo para o escuro. Fiquem juntos, igual remador."),

            // ================= Treva nas Voltas (nível 284, aneis_de_mehen) =================
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.title", "Dark in the Coils", "Treva nas Voltas"),
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.description",
                "A creeping dark has slid into the inner coils of Mehen and makes the serpent forget which way it turns. Djedi asked the cousins to chase it so the rings remember their road.",
                "Uma treva rastejante entrou nas voltas de dentro de Mehen e faz a serpente esquecer para que lado ela gira. O Djedi pediu aos primos que espantem a treva para os anéis lembrarem a estrada."),
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.obj_chase_the_creeping_dark", "Chase the creeping dark out of the coils of Mehen", "Espantar a treva rastejante das voltas de Mehen"),
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.journal",
                "When the dark left the coils, the whole serpent turned once, slowly, and the stars over the river shifted. Maithe says she heard it purr. Djedi says it was him.",
                "Quando a treva saiu das voltas, a serpente inteira girou uma vez, devagar, e as estrelas sobre o rio mudaram de lugar. A Maithe diz que ouviu ela ronronar. O Djedi diz que foi ele."),
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.offer",
                "Mehen is confused. A confused serpent is a confused road, and the barque gets lost. There is dark in the coils: eight pieces of it. Shoo it.",
                "Mehen está confusa. Serpente confusa é estrada confusa, e a barca se perde. Tem treva nas voltas: oito pedaços. Enxotem."),
            new LocalizationEntry("quest.city_mesektet_dark_in_the_coils.active",
                "The dark goes where the light is not. Carry the light in, it has to go out.",
                "A treva vai para onde a luz não está. Levem a luz para dentro, que ela tem de sair."),

            // ================= Serpentes na Beira Fervente (nível 288, beira_fervente) =================
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.title", "Snakes on the Boiling Shore", "Serpentes na Beira Fervente"),
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.description",
                "Sand snakes nest on the boiling shore of the Lake of Fire, where the barque takes on water that does not burn the good. Sinuhe asked the cousins to clear the shore so his rowers can fill the jars.",
                "Serpentes de areia fazem ninho na beira fervente do Lago de Fogo, onde a barca pega a água que não queima quem é bom. O Sinuhe pediu aos primos que limpem a beira para os remadores encherem as jarras."),
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.obj_chase_the_snakes", "Chase the sand snakes off the boiling shore", "Espantar as serpentes de areia da beira fervente"),
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.journal",
                "Lavine dipped her hand in the lake and it did not burn. Joaquim did not try. Sinuhe says that was wise, and gave him the first cup of the cold water instead.",
                "A Lavine molhou a mão no lago e não queimou. O Joaquim não quis tentar. O Sinuhe disse que foi sabedoria, e deu a ele a primeira caneca da água fria."),
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.offer",
                "The Lake of Fire burns only what is false. The snakes on its shore are true enough to bite. Seven of them. Your grandparents would like this lake.",
                "O Lago de Fogo só queima o que é falso. As serpentes da beira são verdadeiras o bastante para morder. Sete delas. Os avós de vocês iam gostar desse lago."),
            new LocalizationEntry("quest.city_mesektet_snakes_on_the_boiling_shore.active",
                "Mind the steam. Snakes hide where you cannot see your feet.",
                "Cuidado com o vapor. Serpente se esconde onde vocês não enxergam o pé."),

            // ================= Betume Vivo nos Poços (nível 314, pocos_de_betume) =================
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.title", "Living Tar in the Wells", "Betume Vivo nos Poços"),
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.description",
                "The bitumen that seals the ziggurat's water clock comes from the tar wells, and the tar there has come alive with the mud of the dark. Utnapishtim asked the cousins to scrape it back so the clock does not run out.",
                "O betume que veda o relógio de água do zigurate vem dos poços de betume, e o piche de lá ganhou vida com o lodo da treva. O Utnapishtim pediu aos primos que raspem o betume vivo para o relógio não parar."),
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.obj_scrape_the_living_tar", "Scrape the living tar out of the wells", "Raspar o betume vivo dos poços"),
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.journal",
                "Utnapishtim says he once sealed a boat so well it floated through a flood. Ícaro asked to see the clock's insides. Utnapishtim let him, and Ícaro came back covered in pitch and very happy.",
                "O Utnapishtim diz que uma vez vedou um barco tão bem que ele atravessou um dilúvio. O Ícaro pediu para ver as entranhas do relógio. O Utnapishtim deixou, e o Ícaro voltou coberto de piche e muito feliz."),
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.offer",
                "My clock drips, cousins, and the pitch to seal it is crawling about in the wells. Seven blobs of it. Scrape them, and bring me the honest tar.",
                "O meu relógio está pingando, primos, e o piche para vedar está andando sozinho nos poços. Sete bolotas. Raspem, e me tragam o betume honesto."),
            new LocalizationEntry("quest.city_dur_jarras_living_tar_in_the_wells.active",
                "The living tar sticks to boots. Joaquim, take yours off before you come in.",
                "Betume vivo gruda na bota. Joaquim, tira a sua antes de entrar."),

            // ================= Garças no Juncal de Piche (nível 318, juncal_de_piche) =================
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.title", "Herons in the Pitch Reeds", "Garças no Juncal de Piche"),
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.description",
                "Tar herons stalk the pitch reeds where Sin-leqi-unninni cuts the reed pens for his tablets, and they snap every pen in half. He asked the cousins to chase them so he can keep writing the story down.",
                "Garças de piche rondam o juncal onde o Sin-leqi-unninni corta os cálamos das tábuas, e quebram cada cálamo no meio. Ele pediu aos primos que espantem as garças para ele continuar escrevendo a história."),
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.obj_chase_the_tar_herons", "Chase the tar herons out of the pitch reeds", "Espantar as garças de piche do juncal"),
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.journal",
                "Sin-leqi-unninni cut a reed pen for each of us. Maria wrote her first line in wedges: five cousins went to the reeds. He says it is the shortest good story he has ever read.",
                "O Sin-leqi-unninni cortou um cálamo para cada um de nós. A Maria escreveu a primeira linha em cunhas: cinco primos foram ao juncal. Ele diz que é a história boa mais curta que já leu."),
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.offer",
                "No reeds, no pens. No pens, no tablets. No tablets, and nobody remembers that you came. Six herons, please.",
                "Sem junco, sem cálamo. Sem cálamo, sem tábua. Sem tábua, ninguém lembra que vocês vieram. Seis garças, por favor."),
            new LocalizationEntry("quest.city_dur_jarras_herons_in_the_pitch_reeds.active",
                "They stand still until you are close. Do not stand still too.",
                "Elas ficam paradas até vocês chegarem perto. Não fiquem parados também."),

            // ================= Cedros Raivosos (nível 322, cedral_de_hobabish) =================
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.title", "Angry Cedars", "Cedros Raivosos"),
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.description",
                "The cedars of Hobabish's forest were cut once by greedy hands and have been angry ever since; now the shadow has woken them and they swing at every traveller. Utnapishtim asked the cousins to calm them.",
                "Os cedros da floresta de Hobabish foram cortados uma vez por mãos gananciosas e ficaram raivosos desde então; agora a sombra acordou eles e eles batem em todo viajante. O Utnapishtim pediu aos primos que acalmem os cedros."),
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.obj_calm_the_cedars", "Calm the angry cedars of Hobabish", "Acalmar os cedros raivosos de Hobabish"),
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.journal",
                "Lavine said sorry to every cedar, one by one, for the old axes. The last one dropped a cone at her feet. Utnapishtim says Hobabish himself would have liked her.",
                "A Lavine pediu desculpa para cada cedro, um por um, pelos machados antigos. O último deixou cair uma pinha no pé dela. O Utnapishtim diz que o próprio Hobabish ia gostar dela."),
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.offer",
                "The cedars remember the axes and the shadow reminds them every night. Six of them swing at the road. Calm them, do not cut them, they have had enough of that.",
                "Os cedros lembram dos machados e a sombra lembra eles toda noite. Seis batem na estrada. Acalmem, não cortem, que disso eles já tiveram demais."),
            new LocalizationEntry("quest.city_dur_jarras_angry_cedars.active",
                "Speak low in the cedar wood. Trees hear better than they see.",
                "Falem baixo no cedral. Árvore escuta melhor do que enxerga."),

            // ================= Mantos de Brilho dos Anciãos (nível 326, cedros_anciaos) =================
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.title", "Glow Mantles of the Elders", "Mantos de Brilho dos Anciãos"),
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.description",
                "Glow mantles hang from the eldest cedars and drink the light stored in the resin, the light the tablets of the Book of the Giants say the trees keep for the end. Sin-leqi-unninni asked the cousins to chase them off.",
                "Mantos de brilho se penduram nos cedros mais velhos e bebem a luz guardada na resina, a luz que as tábuas do Livro dos Gigantes dizem que as árvores guardam para o fim. O Sin-leqi-unninni pediu aos primos que espantem os mantos."),
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.obj_chase_the_glow_mantles", "Chase the glow mantles off the elder cedars", "Espantar os mantos de brilho dos cedros anciãos"),
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.journal",
                "Sin-leqi-unninni read us the tablet about the elder cedars. Maithe asked who wrote it. He said a giant who could not sleep. Joaquim fell asleep at that exact line.",
                "O Sin-leqi-unninni leu para a gente a tábua dos cedros anciãos. A Maithe perguntou quem escreveu. Ele disse que foi um gigante que não conseguia dormir. O Joaquim dormiu bem nessa linha."),
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.offer",
                "The tablets say the elder cedars keep light in their resin. The glow mantles say thank you and drink it. Seven of them. Make them stop saying thank you.",
                "As tábuas dizem que os cedros anciãos guardam luz na resina. Os mantos de brilho dizem obrigado e bebem. Sete deles. Façam eles pararem de agradecer."),
            new LocalizationEntry("quest.city_dur_jarras_glow_mantles_of_the_elders.active",
                "They shine brightest just after they drink. Strike them then.",
                "Eles brilham mais logo depois de beber. Batam nessa hora."),

            // ================= Gigantes da Cova da Fumaça (nível 354, corredores_de_cinza) =================
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.title", "Giants of the Smoke Cave", "Gigantes da Cova da Fumaça"),
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.description",
                "The first of the five caves of the dark is smoke, and smoke giants walk its ash corridors and blow out the lamps Pamour's soldiers carry down. Pamour asked the cousins to chase them back.",
                "A primeira das cinco covas da treva é a fumaça, e gigantes de fumaça andam pelos corredores de cinza e apagam as lâmpadas que os soldados do Pamour levam para baixo. O Pamour pediu aos primos que empurrem eles de volta."),
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.obj_chase_the_smoke_giants", "Chase the smoke giants out of the ash corridors", "Espantar os gigantes de fumaça dos corredores de cinza"),
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.journal",
                "Pamour lit a lamp for each of us and wrote our names on the wall of the rampart, next to the soldiers. Maria fixed the spelling of Ícaro's. Pamour says the wall has never been so well written.",
                "O Pamour acendeu uma lâmpada para cada um de nós e escreveu os nossos nomes na parede da muralha, junto dos soldados. A Maria corrigiu a grafia do Ícaro. O Pamour diz que a parede nunca foi tão bem escrita."),
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.offer",
                "Down there are five caves, one for each element of the dark: smoke, fire, wind, mud, darkness. We start with the smoke. Six giants of it. Keep your lamps high.",
                "Lá embaixo são cinco covas, uma para cada elemento da treva: fumaça, fogo, vento, lodo e escuridão. Começamos pela fumaça. Seis gigantes dela. Lâmpada no alto."),
            new LocalizationEntry("quest.city_ultima_lampada_smoke_giants.active",
                "Smoke giants are big and empty. Strike through them, not at them.",
                "Gigante de fumaça é grande e oco. Batam atravessando, não em cima."),

            // ================= Lobos do Fogo Devorador (nível 358, cova_do_fogo_devorador) =================
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.title", "Wolves of the Consuming Fire", "Lobos do Fogo Devorador"),
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.description",
                "In the cave of the consuming fire, ember wolves hunt the messengers who carry Makarios's letters down to the soldiers. He asked the cousins to drive them off so the letters arrive unburnt.",
                "Na cova do fogo devorador, lobos de brasa caçam os mensageiros que levam as cartas do Makarios para os soldados lá embaixo. Ele pediu aos primos que espantem os lobos para as cartas chegarem sem queimar."),
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.obj_chase_the_ember_wolves", "Drive the ember wolves out of the cave of fire", "Espantar os lobos de brasa da cova do fogo"),
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.journal",
                "Makarios showed us a letter Grandpa Jorge wrote him years ago. It is four pages about the weather and one line at the end: take care of the lamps. Maithe read it twice.",
                "O Makarios mostrou uma carta que o Vô Jorge escreveu para ele anos atrás. São quatro páginas sobre o tempo e uma linha no fim: cuida das lâmpadas. A Maithe leu duas vezes."),
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.offer",
                "The second cave burns, and it eats paper first. Eight wolves are waiting for my messengers. Go ahead of them, please.",
                "A segunda cova queima, e come papel primeiro. Oito lobos esperam os meus mensageiros. Vão na frente deles, por favor."),
            new LocalizationEntry("quest.city_ultima_lampada_ember_wolves.active",
                "Fire wolves run in circles. Stand in the middle and let them come.",
                "Lobo de fogo corre em círculo. Fiquem no meio e deixem eles virem."),

            // ================= Leões da Cinza Quente (nível 364, saloes_de_cinza_quente) =================
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.title", "Lions of the Hot Ash", "Leões da Cinza Quente"),
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.description",
                "In the deepest halls of the fire cave, lions of hot smoke guard the ashes as if they were treasure. Pamour's soldiers cannot hold the lamp line there, so he asked the cousins.",
                "Nos salões mais fundos da cova do fogo, leões de fumaça quente guardam as cinzas como se fossem tesouro. Os soldados do Pamour não conseguem segurar a fila de lâmpadas ali, então ele pediu aos primos."),
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.obj_chase_the_hot_lions", "Chase the hot smoke lions out of the ash halls", "Espantar os leões de fumaça quente dos salões de cinza"),
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.journal",
                "The lions guarded nothing: only ash, warm and grey. Lavine says they were guarding it because nobody ever told them it was empty. Pamour wrote that on the wall too.",
                "Os leões não guardavam nada: só cinza, morna e cinzenta. A Lavine diz que eles guardavam porque ninguém nunca contou que estava vazio. O Pamour escreveu isso na parede também."),
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.offer",
                "Five lions in the ash halls. Greedy beasts, they guard what is worth nothing. Do not let them make you greedy too.",
                "Cinco leões nos salões de cinza. Bichos gulosos, guardam o que não vale nada. Não deixem eles deixarem vocês gulosos também."),
            new LocalizationEntry("quest.city_ultima_lampada_hot_smoke_lions.active",
                "The lions roar before they leap. That is the only polite thing about them.",
                "Os leões rugem antes de pular. É a única educação que eles têm."),

            // ================= Morcegos do Vento Destruidor (nível 368, cova_do_vento_destruidor) =================
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.title", "Bats of the Destroying Wind", "Morcegos do Vento Destruidor"),
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.description",
                "In the third cave the destroying wind carries blade bats that slice the letters out of the messengers' hands. Makarios asked the cousins to chase them before his last letter to his sons blows away.",
                "Na terceira cova o vento destruidor carrega morcegos-lâmina que cortam as cartas da mão dos mensageiros. O Makarios pediu aos primos que espantem eles antes que a última carta dele para os filhos voe embora."),
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.obj_chase_the_blade_bats", "Chase the blade bats out of the cave of wind", "Espantar os morcegos-lâmina da cova do vento"),
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.journal",
                "Ícaro tied the letter to a stone so the wind could not take it. Makarios said that was the most practical thing anyone had done for his letters in thirty years.",
                "O Ícaro amarrou a carta numa pedra para o vento não levar. O Makarios disse que foi a coisa mais prática que alguém fez pelas cartas dele em trinta anos."),
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.offer",
                "I wrote my sons a short letter for once, and the wind still took it. Eight bats in the cave of the destroying wind. Please.",
                "Escrevi uma carta curta para os meus filhos pela primeira vez, e o vento levou mesmo assim. Oito morcegos na cova do vento destruidor. Por favor."),
            new LocalizationEntry("quest.city_ultima_lampada_blade_bats.active",
                "They fly with the gust. Turn your back to the wind and they come to your front.",
                "Eles voam com a rajada. Virem as costas para o vento que eles vêm pela frente."),

            // ================= Águias Negras no Poço (nível 372, cova_do_vento_destruidor) =================
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.title", "Black Eagles in the Shaft", "Águias Negras no Poço"),
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.description",
                "Black eagles nest in the shaft of the wind cave and dive on the soldiers who climb the air currents with their lamps. Pamour asked the cousins to clear the nests from the shaft.",
                "Águias negras fazem ninho no poço da cova do vento e mergulham nos soldados que sobem as correntes de ar com as lâmpadas. O Pamour pediu aos primos que limpem os ninhos do poço."),
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.obj_chase_the_black_eagles", "Chase the black eagles out of the wind shaft", "Espantar as águias negras do poço do vento"),
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.journal",
                "Maithe rode the current up the shaft with her eyes closed and said the wind there sounded like it was lost. Pamour said every wind down here is lost, and that is why it is angry.",
                "A Maithe subiu a corrente do poço de olhos fechados e disse que o vento ali parecia perdido. O Pamour disse que todo vento aqui embaixo é perdido, e é por isso que é bravo."),
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.offer",
                "The bats were the small ones. The eagles are the big ones, and they nest in the shaft. Seven of them. Hold your lamps tight on the way up.",
                "Os morcegos eram os pequenos. As águias são as grandes, e fazem ninho no poço. Sete delas. Segurem firme a lâmpada na subida."),
            new LocalizationEntry("quest.city_ultima_lampada_black_eagles.active",
                "An eagle dives once. Step aside and it hits the wall.",
                "Águia mergulha uma vez. Saiam da frente que ela bate na parede."),

            // ================= Harpias nas Plataformas Soltas (nível 376, plataformas_soltas) =================
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.title", "Harpies on the Loose Platforms", "Harpias nas Plataformas Soltas"),
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.description",
                "Wind harpies shriek over the loose platforms of the wind cave and read the letters they steal aloud, wrong. Makarios cannot bear it and asked the cousins to chase them.",
                "Harpias de vento gritam sobre as plataformas soltas da cova do vento e leem em voz alta as cartas que roubam, tudo errado. O Makarios não aguenta e pediu aos primos que espantem elas."),
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.obj_chase_the_wind_harpies", "Chase the wind harpies off the loose platforms", "Espantar as harpias de vento das plataformas soltas"),
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.journal",
                "Joaquim read Makarios's letter back to him the right way, slowly, every word. Makarios cried. Joaquim says it was the dust. Maria says it was not.",
                "O Joaquim leu a carta do Makarios de volta para ele do jeito certo, devagar, palavra por palavra. O Makarios chorou. O Joaquim diz que foi a poeira. A Maria diz que não foi."),
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.offer",
                "They read my letters out loud and change the words. My sons will think I am a fool. Seven harpies. Then come back and read me what they said.",
                "Elas leem as minhas cartas em voz alta e trocam as palavras. Os meus filhos vão achar que eu sou bobo. Sete harpias. Depois voltem e me contem o que elas disseram."),
            new LocalizationEntry("quest.city_ultima_lampada_wind_harpies.active",
                "The platforms move. Jump when they rise, never when they fall.",
                "As plataformas mexem. Pulem quando elas sobem, nunca quando descem."),

            // ================= Peixes da Cova do Lodo (nível 384, cova_do_lodo) =================
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.title", "Fish of the Mud Cave", "Peixes da Cova do Lodo"),
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.description",
                "The fourth cave is mud and dark water, and fish of the dark bite the lamp floats Pamour's soldiers send down the flooded halls. He asked the cousins to chase them so the floats reach the bottom.",
                "A quarta cova é lodo e água escura, e peixes da treva mordem as boias de lâmpada que os soldados do Pamour mandam pelos salões alagados. Ele pediu aos primos que espantem os peixes para as boias chegarem ao fundo."),
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.obj_chase_the_dark_fish", "Chase the dark fish out of the mud cave", "Espantar os peixes da treva da cova do lodo"),
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.journal",
                "Lavine let a float go and we watched its light drop down and down into the mud until it was a star. Pamour says somewhere at the bottom it is the only light, and that is enough.",
                "A Lavine soltou uma boia e a gente ficou olhando a luz descer, descer no lodo, até virar estrela. O Pamour diz que em algum lugar lá no fundo ela é a única luz, e isso basta."),
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.offer",
                "Mud and water now. My floats carry light to the bottom, and eight dark fish eat the light. Do not fall in, the mud keeps what it catches.",
                "Agora é lodo e água. As minhas boias levam luz até o fundo, e oito peixes da treva comem a luz. Não caiam, que o lodo guarda o que pega."),
            new LocalizationEntry("quest.city_ultima_lampada_dark_fish.active",
                "They come up to the light. Hold a lamp over the water and wait.",
                "Eles sobem atrás da luz. Segurem uma lâmpada sobre a água e esperem."),

            // ================= Enguias nos Salões Alagados (nível 388, saloes_alagados) =================
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.title", "Eels in the Flooded Halls", "Enguias nos Salões Alagados"),
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.description",
                "Great eels coil in the flooded halls and drag the letter rafts under. Makarios has been writing to his sons for thirty years and half of the letters sleep in that water. He asked the cousins to chase the eels.",
                "Enguias grandes se enrolam nos salões alagados e puxam as jangadas de cartas para o fundo. O Makarios escreve para os filhos há trinta anos e metade das cartas dorme naquela água. Ele pediu aos primos que espantem as enguias."),
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.obj_chase_the_great_eels", "Chase the great eels out of the flooded halls", "Espantar as enguias grandes dos salões alagados"),
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.journal",
                "When the eels let go, an old raft came up with a letter still sealed in wax. Makarios would not open it. He says it was the one where he said sorry, and that it arrived anyway. Maithe held his hand the whole way back.",
                "Quando as enguias soltaram, uma jangada velha subiu com uma carta ainda lacrada. O Makarios não quis abrir. Disse que era a carta em que ele pedia desculpa, e que ela chegou mesmo assim. A Maithe segurou a mão dele o caminho todo de volta."),
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.offer",
                "Six eels sit on half my life's letters. I do not need them back. I need the next ones to pass.",
                "Seis enguias estão sentadas em cima de metade das cartas da minha vida. Não preciso delas de volta. Preciso que as próximas passem."),
            new LocalizationEntry("quest.city_ultima_lampada_great_eels.active",
                "Eels pull. Do not pull back. Let go and strike.",
                "Enguia puxa. Não puxem de volta. Soltem e batam."),

            // ================= Polvos nas Comportas (nível 394, comportas_artifices) =================
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.title", "Octopus at the Sluices", "Polvos nas Comportas"),
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.description",
                "Mud octopus have wrapped the artificers' sluices of the mud cave, so the water can neither rise nor fall. Pamour asked the cousins to pull them off before the lower halls drown for good.",
                "Polvos de lodo se enrolaram nas comportas dos artífices da cova do lodo, e a água não sobe nem desce. O Pamour pediu aos primos que arranquem eles antes que os salões de baixo afoguem de vez."),
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.obj_chase_the_mud_octopus", "Pull the mud octopus off the sluices", "Arrancar os polvos de lodo das comportas"),
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.journal",
                "Ícaro read the sluice gears like a book and found the one the octopus had bent. He fixed it with a hairpin of Maria's. Pamour gave him a soldier's medal. Maria wants her hairpin back.",
                "O Ícaro leu as engrenagens da comporta igual livro e achou a que o polvo tinha entortado. Consertou com um grampo da Maria. O Pamour deu uma medalha de soldado para ele. A Maria quer o grampo de volta."),
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.offer",
                "Six octopus on the sluices of the artificers. The water is stuck, and stuck water rots. Pull, cousins, and mind the ink.",
                "Seis polvos nas comportas dos artífices. A água travou, e água travada apodrece. Puxem, primos, e cuidado com a tinta."),
            new LocalizationEntry("quest.city_ultima_lampada_mud_octopus.active",
                "They let go of the gate to grab you. That is when the gate is free.",
                "Eles soltam a comporta para agarrar vocês. É aí que a comporta fica livre."),

            // ================= Serpentes Cegas da Treva (nível 398, cova_da_treva) =================
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.title", "Blind Serpents of the Dark", "Serpentes Cegas da Treva"),
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.description",
                "The fifth cave is the darkness itself, and blind serpents slide along the floor feeling for the warmth of the lamps. Makarios writes the last letters of the soldiers who go down there, and asked the cousins to clear the way.",
                "A quinta cova é a própria escuridão, e serpentes cegas deslizam pelo chão procurando o calor das lâmpadas. O Makarios escreve as últimas cartas dos soldados que descem lá, e pediu aos primos que limpem o caminho."),
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.obj_chase_the_blind_serpents", "Chase the blind serpents out of the cave of darkness", "Espantar as serpentes cegas da cova da treva"),
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.journal",
                "In the dark Maithe sang Grandma Edna's tacho song and we followed her voice out. Makarios wrote it down for the soldiers. He says it is a better map than his.",
                "No escuro a Maithe cantou a música do tacho da Vó Edna e a gente seguiu a voz dela para fora. O Makarios escreveu a letra para os soldados. Ele diz que é um mapa melhor que o dele."),
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.offer",
                "The darkness down there is not night. Night ends. Seven blind serpents in it, feeling for warmth. Go warm, come back warm.",
                "A escuridão lá embaixo não é noite. Noite acaba. Sete serpentes cegas nela, procurando calor. Vão quentinhos, voltem quentinhos."),
            new LocalizationEntry("quest.city_ultima_lampada_blind_serpents.active",
                "They cannot see you, they feel you. Stand still and let them miss.",
                "Elas não enxergam vocês, sentem. Fiquem parados e deixem elas errarem."),

            // ================= Lagartos de Sombra na Fila de Lâmpadas (nível 402, cova_da_treva) =================
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.title", "Shadow Lizards on the Lamp Line", "Lagartos de Sombra na Fila de Lâmpadas"),
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.description",
                "Shadow lizards lick out the lamps of the line Pamour's soldiers keep across the cave of darkness, one by one, from the far end. Pamour asked the cousins to chase them before the line reaches his rampart dark.",
                "Lagartos de sombra lambem as lâmpadas da fila que os soldados do Pamour mantêm na cova da treva, uma por uma, da ponta de lá. O Pamour pediu aos primos que espantem os lagartos antes que a fila chegue apagada na muralha."),
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.obj_chase_the_shadow_lizards", "Chase the shadow lizards off the lamp line", "Espantar os lagartos de sombra da fila de lâmpadas"),
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.journal",
                "We relit the whole line, forty lamps. Pamour walked it end to end and touched every one. He says he did the same with Grandpa Jorge, long ago, and that Jorge counted them wrong.",
                "A gente reacendeu a fila inteira, quarenta lâmpadas. O Pamour andou de ponta a ponta e tocou em cada uma. Diz que fez o mesmo com o Vô Jorge, há muito tempo, e que o Jorge contou errado."),
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.offer",
                "The line across the darkness is going out from the far end. Six lizards are licking it. Each lamp is a soldier who can find his way home. Go.",
                "A fila no meio da treva está apagando da ponta de lá. Seis lagartos estão lambendo. Cada lâmpada é um soldado que acha o caminho de casa. Vão."),
            new LocalizationEntry("quest.city_ultima_lampada_shadow_lizards.active",
                "Relight each lamp as you pass. The lizards hate a lit path behind them.",
                "Reacendam cada lâmpada quando passarem. Lagarto odeia caminho aceso atrás dele."),

            // ================= Dragões dos Túneis Cegos (nível 406, tuneis_cegos) =================
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.title", "Dragons of the Blind Tunnels", "Dragões dos Túneis Cegos"),
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.description",
                "Lesser shadow dragons sleep in the blind tunnels that lead to the Ponte do Novelo, and wake hungry whenever a messenger passes. Makarios asked the cousins to chase them, so his last letter, the one for all the soldiers, can cross.",
                "Dragões de sombra menores dormem nos túneis cegos que levam à Ponte do Novelo, e acordam com fome sempre que passa um mensageiro. O Makarios pediu aos primos que espantem eles, para a última carta dele, a de todos os soldados, atravessar."),
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.obj_chase_the_shadow_dragons", "Chase the lesser shadow dragons out of the blind tunnels", "Espantar os dragões de sombra menores dos túneis cegos"),
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.journal",
                "Makarios let us read the letter for all the soldiers. It says: the light is coming back, hold on. Lavine says that is the whole letter. Makarios says it took him thirty years to make it that short.",
                "O Makarios deixou a gente ler a carta para todos os soldados. Ela diz: a luz está voltando, aguentem. A Lavine diz que é a carta inteira. O Makarios diz que levou trinta anos para ela ficar curta assim."),
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.offer",
                "This letter is for all of them, and five small dragons sleep in its way. You have been through every cave. One more tunnel.",
                "Essa carta é para todos eles, e cinco dragões pequenos dormem no caminho dela. Vocês já passaram por todas as covas. Só mais um túnel."),
            new LocalizationEntry("quest.city_ultima_lampada_lesser_dragons.active",
                "A small dragon is still a dragon. Stay out of its breath.",
                "Dragão pequeno ainda é dragão. Fiquem fora do bafo."),

            // ================= Sombras no Rio de Luz (nível 432, foz_oeste) =================
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.title", "Shadows in the River of Light", "Sombras no Rio de Luz"),
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.description",
                "Swimming shadows slide against the River of Light at its western mouth and muddy the light Ammo's bales pour into it. Ammo asked the cousins to chase them so the gifts of every city flow up clean.",
                "Sombras nadadoras nadam contra o Rio de Luz na foz oeste e sujam a luz que os fardos do Ammo despejam nele. O Ammo pediu aos primos que espantem as sombras para os presentes de cada cidade subirem limpos."),
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.obj_chase_the_swimming_shadows", "Chase the swimming shadows out of the western mouth", "Espantar as sombras nadadoras da foz oeste"),
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.journal",
                "Ammo poured Grandma Edna's Golden Brick into the river, a spoonful, and the water turned the colour of the tacho. Joaquim wanted to eat the rest. Ammo let him.",
                "O Ammo jogou uma colher do Torrão Dourado da Vó Edna no rio, e a água ficou da cor do tacho. O Joaquim quis comer o resto. O Ammo deixou."),
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.offer",
                "Up here the bales open into the river and the river carries the light home. Seven shadows swim the wrong way at the mouth. Chase them downstream.",
                "Aqui em cima os fardos se abrem no rio e o rio leva a luz para casa. Sete sombras nadam ao contrário na foz. Empurrem elas rio abaixo."),
            new LocalizationEntry("quest.city_cais_coluna_shadows_in_the_light_river.active",
                "Shadows are slow in the current. Swim with it and you will catch them.",
                "Sombra é lenta na correnteza. Nadem a favor que vocês alcançam."),

            // ================= O Porão da Barca da Lua (nível 436, conves_da_lua) =================
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.title", "The Hold of the Moon Barque", "O Porão da Barca da Lua"),
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.description",
                "The Moon Barque fills with light as it waxes and pours it into the Sun when it is full. Shadows have crept up from its hold onto the deck and drink it as it fills. Adda asked the cousins to chase them back down.",
                "A Barca da Lua enche de luz enquanto cresce e despeja tudo no Sol quando fica cheia. Sombras subiram do porão para o convés e bebem a luz enquanto ela enche. O Adda pediu aos primos que empurrem elas de volta para baixo."),
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.obj_chase_the_hold_shadows", "Chase the hold shadows off the deck of the Moon Barque", "Espantar as sombras do porão do convés da Barca da Lua"),
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.journal",
                "On the deck of the Moon Barque Maria remembered the moon that would not fill, back home. Adda says that is why it would not: the shadows were drinking it from up here. Tonight it was full.",
                "No convés da Barca da Lua a Maria lembrou da lua que não enchia, lá em casa. O Adda diz que era por isso: as sombras bebiam ela daqui de cima. Hoje à noite ela encheu."),
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.offer",
                "You remember the moon that would not fill? This is why. Six shadows came up from the hold of the barque. Send them down again.",
                "Lembram da lua que não enchia? É por isso. Seis sombras subiram do porão da barca. Mandem elas para baixo de novo."),
            new LocalizationEntry("quest.city_cais_coluna_hold_of_the_moon_barque.active",
                "The deck tilts as the barque fills. Keep to the high side.",
                "O convés inclina quando a barca enche. Fiquem do lado de cima."),

            // ================= Cordas na Proa (nível 442, proa_da_lua) =================
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.title", "Ropes on the Prow", "Cordas na Proa"),
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.description",
                "Living ropes knot themselves round the prow of the Moon Barque and tie it to nothing. Ammo has tied knots on mules for forty years and says these are the worst he has seen. He asked the cousins to untangle them.",
                "Cordas vivas se amarram na proa da Barca da Lua e prendem ela em coisa nenhuma. O Ammo amarra nó em mula há quarenta anos e diz que esses são os piores que já viu. Ele pediu aos primos que desatem as cordas."),
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.obj_untangle_the_living_ropes", "Untangle the living ropes of the prow", "Desatar as cordas vivas da proa"),
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.journal",
                "Ammo taught Ícaro the caravan knot, the one that holds a bale up a mountain and opens with one pull. Ícaro tied it eleven times. Ammo says Grandpa Jorge never learned it.",
                "O Ammo ensinou ao Ícaro o nó de caravana, o que segura fardo na subida da montanha e abre com um puxão. O Ícaro amarrou onze vezes. O Ammo diz que o Vô Jorge nunca aprendeu."),
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.offer",
                "Seven ropes on the prow, tied to nothing and holding the barque back. A rope with no load is a rope with ideas. Untie them.",
                "Sete cordas na proa, amarradas em nada e segurando a barca. Corda sem carga é corda com ideia. Desatem."),
            new LocalizationEntry("quest.city_cais_coluna_ropes_on_the_prow.active",
                "Pull the loose end, never the knot.",
                "Puxem a ponta solta, nunca o nó."),

            // ================= Jarras Rachadas na Roda (nível 446, roda_celeste) =================
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.title", "Cracked Jars on the Wheel", "Jarras Rachadas na Roda"),
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.description",
                "Some of the jars of the Roda Celeste cracked and came alive, spitting the light back out instead of lifting it. Adda asked the cousins to break the cracked ones so he can hang new jars.",
                "Algumas jarras da Roda Celeste racharam e ganharam vida, cuspindo a luz de volta em vez de levantar. O Adda pediu aos primos que quebrem as rachadas para ele pendurar jarras novas."),
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.obj_break_the_cracked_jars", "Break the cracked jars of the Wheel", "Quebrar as jarras rachadas da Roda"),
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.journal",
                "Adda hung the new jars with Lavine passing them up one by one. Twelve jars, one turn. He says the Wheel was lighter by the end, and he does not mean the jars.",
                "O Adda pendurou as jarras novas com a Lavine passando uma por uma. Doze jarras, uma volta. Ele diz que a Roda ficou mais leve no fim, e não está falando das jarras."),
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.offer",
                "My birds are gone, thank you. Now the jars themselves are cracking and spitting. Seven of them. Break the bad ones, I have new ones ready.",
                "As minhas aves foram embora, obrigado. Agora são as próprias jarras que racham e cospem. Sete delas. Quebrem as ruins, que eu tenho novas prontas."),
            new LocalizationEntry("quest.city_cais_coluna_cracked_jars.active",
                "A cracked jar leaks before it throws. Watch for the drip.",
                "Jarra rachada pinga antes de atirar. Olhem a goteira."),

            // ================= Arcontes nas Engrenagens (nível 452, engrenagens_leste) =================
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.title", "Archons in the Gears", "Arcontes nas Engrenagens"),
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.description",
                "Little archons, like wind-up toys, have climbed into the eastern gears of the Wheel to make it turn backwards. Ammo saw them from his cart and asked the cousins to chase them out.",
                "Arcontes pequenos, parecidos com brinquedo de corda, entraram nas engrenagens do leste da Roda para fazer ela girar ao contrário. O Ammo viu da carroça e pediu aos primos que tirem eles de lá."),
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.obj_chase_the_toy_archons", "Chase the toy archons out of the eastern gears", "Tirar os arcontes de brinquedo das engrenagens do leste"),
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.journal",
                "Ícaro found the key one archon had used to wind itself up and put it in his pocket. He says he wants to know what it opens. Ammo says some things are better not opened. Ícaro did not give it back.",
                "O Ícaro achou a chave com que um arconte dava corda em si mesmo e guardou no bolso. Diz que quer saber o que ela abre. O Ammo diz que tem coisa que é melhor não abrir. O Ícaro não devolveu."),
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.offer",
                "Five tin archons are in the gears, winding the Wheel the wrong way. They look like toys. Toys do not usually bite.",
                "Cinco arcontes de lata estão nas engrenagens, dando corda na Roda ao contrário. Parecem brinquedo. Brinquedo não costuma morder."),
            new LocalizationEntry("quest.city_cais_coluna_toy_archons.active",
                "When one runs out of wind it stops. Make them run.",
                "Quando a corda acaba, eles param. Façam eles correrem."),

            // ================= Os Arcontes nas Correntes (nível 456, esferas_dos_arcontes) =================
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.title", "The Archons in Their Chains", "Os Arcontes nas Correntes"),
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.description",
                "In the spheres where the Living Spirit chained the archons long ago, some have stretched their chains as far as the path to the Garden of Light. Adda asked the cousins to push them back to their spheres.",
                "Nas esferas onde o Espírito Vivo acorrentou os arcontes há muito tempo, alguns esticaram as correntes até o caminho do Jardim de Luz. O Adda pediu aos primos que empurrem eles de volta para as esferas."),
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.obj_chase_the_chained_archons", "Push the chained archons back into their spheres", "Empurrar os arcontes acorrentados de volta para as esferas"),
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.journal",
                "Maithe asked an archon why it pulled so hard. It did not answer. Adda says they always want a little more, and that is the whole of what they are. Maithe said that is sad. Adda said yes.",
                "A Maithe perguntou a um arconte por que ele puxava tanto. Ele não respondeu. O Adda diz que eles sempre querem um pouco mais, e é só isso que eles são. A Maithe disse que é triste. O Adda disse que sim."),
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.offer",
                "The archons are chained in their spheres, and six of them are pulling the chains to the Garden path. Push them back. Do not unchain them, whatever they promise.",
                "Os arcontes estão acorrentados nas esferas, e seis estão puxando as correntes até o caminho do Jardim. Empurrem de volta. Não soltem, prometam eles o que prometerem."),
            new LocalizationEntry("quest.city_cais_coluna_chained_archons.active",
                "A chain has a length. Stay just beyond it and let them pull.",
                "Corrente tem tamanho. Fiquem logo depois dela e deixem eles puxarem."),

            // ================= Gigantes na Órbita Vazia (nível 462, orbita_vazia_leste) =================
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.title", "Giants in the Empty Orbit", "Gigantes na Órbita Vazia"),
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.description",
                "Balloon giants, puffed up with smoke, float in the empty eastern orbit and block the last stretch of Ammo's road to the Garden. Ammo asked the cousins to let the air out of them.",
                "Gigantes-balão, inchados de fumaça, flutuam na órbita vazia do leste e fecham o último trecho da estrada do Ammo até o Jardim. O Ammo pediu aos primos que esvaziem eles."),
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.obj_chase_the_balloon_giants", "Chase the balloon giants out of the empty orbit", "Espantar os gigantes-balão da órbita vazia"),
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.journal",
                "When the last giant burst, it was only smoke and a squeak. Joaquim laughed so hard he had to sit on Ammo's cart. Ammo says the mule laughed too.",
                "Quando o último gigante estourou, era só fumaça e um chiado. O Joaquim riu tanto que teve de sentar na carroça do Ammo. O Ammo diz que a mula riu junto."),
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.offer",
                "Five giants of smoke in the empty orbit, all puffed up and full of nothing. My road to the Garden is behind them. A pin would do, but strike them anyway.",
                "Cinco gigantes de fumaça na órbita vazia, todos estufados e cheios de nada. A minha estrada para o Jardim está atrás deles. Um alfinete resolvia, mas batam assim mesmo."),
            new LocalizationEntry("quest.city_cais_coluna_balloon_giants.active",
                "They are big but light. Strike low and they tip over.",
                "São grandes mas leves. Batam embaixo que eles tombam."),

            // ================= Ladrões no Jardim de Luz (nível 466, pergola_do_jardineiro) =================
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.title", "Thieves in the Garden of Light", "Ladrões no Jardim de Luz"),
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.description",
                "Thieves of Āz, the greed of the dark, slip into the Garden of Light and pick the flowers of light before they open. Adda keeps the gardener's pergola and asked the cousins to chase them out.",
                "Ladrões de Āz, a cobiça da treva, entram no Jardim de Luz e colhem as flores de luz antes de abrirem. O Adda cuida da pérgula do jardineiro e pediu aos primos que espantem eles."),
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.obj_chase_the_garden_thieves", "Chase the thieves of Āz out of the Garden", "Espantar os ladrões de Āz do Jardim"),
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.journal",
                "A thief dropped a flower and Lavine picked it up and gave it back to the garden, in the ground. It opened the next morning. Adda says Grandma Edna would have done the same, and then made jam.",
                "Um ladrão deixou cair uma flor e a Lavine pegou e devolveu para o jardim, na terra. Ela abriu na manhã seguinte. O Adda diz que a Vó Edna faria o mesmo, e depois faria doce."),
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.offer",
                "The thieves of Āz pick what is not ripe, because they cannot wait. Seven of them in my Garden. Let the flowers open.",
                "Os ladrões de Āz colhem o que não está maduro, porque não sabem esperar. Sete deles no meu Jardim. Deixem as flores abrirem."),
            new LocalizationEntry("quest.city_cais_coluna_thieves_in_the_garden.active",
                "They run with full hands. Full hands cannot fight.",
                "Eles correm de mão cheia. Mão cheia não briga."),

            // ================= Gaivotas na Barca do Sol (nível 474, conves_do_sol) =================
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.title", "Gulls on the Sun Barque", "Gaivotas na Barca do Sol"),
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.description",
                "Gulls dimmed by the last of the shadow follow the Sun Barque and steal the light the Moon Barque pours into it. Ammo says gulls are gulls even in the sky, and asked the cousins to chase them.",
                "Gaivotas apagadas pelo resto da sombra seguem a Barca do Sol e roubam a luz que a Barca da Lua despeja nela. O Ammo diz que gaivota é gaivota até no céu, e pediu aos primos que espantem elas."),
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.obj_chase_the_dimmed_gulls", "Chase the dimmed gulls off the Sun Barque", "Espantar as gaivotas apagadas da Barca do Sol"),
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.journal",
                "From the deck of the Sun Barque you can see the whole road down: the island, the cities, the Vila. Maria found Grandma Edna's house and waved. Ammo swears somebody waved back.",
                "Do convés da Barca do Sol dá para ver a estrada toda lá embaixo: a ilha, as cidades, a Vila. A Maria achou a casa da Vó Edna e acenou. O Ammo jura que alguém acenou de volta."),
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.offer",
                "I saw gulls on the Taa Pwani quay, gulls on the Lua Branca racks, and now gulls on the Sun. Seven of them. Same trouble, higher up.",
                "Vi gaivota no cais de Taa Pwani, gaivota nos varais da Lua Branca, e agora gaivota no Sol. Sete delas. Mesmo problema, mais alto."),
            new LocalizationEntry("quest.city_cais_coluna_gulls_on_the_sun_barque.active",
                "Gulls hate noise. Joaquim, sing.",
                "Gaivota odeia barulho. Joaquim, canta."),

            // ================= Cordas de Fumaça na Vela (nível 478, vela_do_sol) =================
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.title", "Smoke Ropes on the Sail", "Cordas de Fumaça na Vela"),
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.description",
                "Ropes of smoke have tied the great sail of the Sun Barque short, so it catches less of the light it carries to the Coluna. Adda asked the cousins to cut them so the sail opens wide one last time before the Varanda.",
                "Cordas de fumaça amarraram curta a grande vela da Barca do Sol, e ela pega menos da luz que leva para a Coluna. O Adda pediu aos primos que cortem as cordas para a vela abrir inteira uma última vez antes da Varanda."),
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.obj_cut_the_smoke_ropes", "Cut the smoke ropes off the sail of the Sun", "Cortar as cordas de fumaça da vela do Sol"),
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.journal",
                "When the sail opened, the light ran up the Coluna like the tacho boiling over. All five of us shouted at once. Adda cried, of course. Then he said: now go home to Grandma Edna and Grandpa Jorge, they are waiting on the porch.",
                "Quando a vela abriu, a luz subiu pela Coluna igual tacho fervendo e derramando. Nós cinco gritamos juntos. O Adda chorou, claro. Depois disse: agora vão para casa, a Vó Edna e o Vô Jorge estão esperando na varanda."),
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.offer",
                "One last knot of smoke on the sail of the Sun. Six ropes. Cut them and the light goes all the way up. I will cry, I warn you now.",
                "Um último nó de fumaça na vela do Sol. Seis cordas. Cortem e a luz sobe até o fim. Eu vou chorar, já aviso."),
            new LocalizationEntry("quest.city_cais_coluna_smoke_ropes_on_the_sail.active",
                "Smoke ropes tighten when you pull. Cut, do not tug.",
                "Corda de fumaça aperta quando puxa. Cortem, não puxem."),
        };

        /// <summary>The late main story's texts travel with the city quests', so every loader and fallback finds them.</summary>
        static CityQuestTexts() => All.AddRange(Rapadura.Gameplay.Quests.LateStoryTexts.All);

        public static void EnsureLoaded(LocalizationManager localization)
        {
            if (localization == null)
            {
                return;
            }

            localization.LoadEntries(All.Where(entry => !localization.HasKey(entry.Key)).ToList());
        }

        /// <summary>pt-BR text of <paramref name="key"/> without a manager, or null.</summary>
        public static string GetFallback(string key)
        {
            LocalizationEntry entry = All.FirstOrDefault(e => e.Key == key);
            return entry?.PtBR;
        }
    }
}
